let SB;
(function initSupabase(){
  function showError(msg){
    var v = document.getElementById("view") || document.body;
    v.innerHTML = '<div style="max-width:520px;margin:80px auto;padding:32px;text-align:center;font-family:system-ui">'
      + '<div style="font-size:40px;margin-bottom:12px">⚠️</div>'
      + '<h2 style="margin:0 0 8px">Problème de chargement</h2>'
      + '<p style="color:#555;line-height:1.6">' + msg + '</p>'
      + '<button onclick="location.reload()" style="margin-top:16px;padding:10px 24px;border-radius:8px;background:#00AEEF;color:#fff;border:none;font-size:15px;cursor:pointer">🔄 Recharger</button>'
      + '</div>';
  }
  // 1. La librairie Supabase est-elle chargée ?
  if(typeof supabase === "undefined" || !supabase.createClient){
    showError("La librairie Supabase n'a pas pu être chargée. Vérifiez votre connexion internet puis rechargez la page.");
    throw new Error("supabase library not loaded");
  }
  // 2. La config est-elle présente ?
  if(typeof SUPABASE_URL === "undefined" || typeof SUPABASE_ANON_KEY === "undefined" || !SUPABASE_URL){
    showError("Configuration manquante (config.js). Rechargez la page.");
    throw new Error("config not loaded");
  }
  // 3. Créer le client
  try {
    SB = supabase.createClient(SUPABASE_URL, SUPABASE_ANON_KEY);
  } catch(e){
    showError("Impossible d'initialiser la connexion : " + e.message);
    throw e;
  }
})();

