/* ============================================================
   TRANSFORMATION CHAMPS  camelCase ↔ snake_case Supabase
   ============================================================ */
const FIELD_TO_DB = {
  clientId:"client_id", devisId:"devis_id", factureId:"facture_id",
  montantHT:"montant_ht", montantTVA:"montant_tva", montantTTC:"montant_ttc",
  createdAt:"created_at", roleId:"role_id", caisseId:"caisse_id",
  seqDevis:"seq_devis", seqFacture:"seq_facture", seqCommande:"seq_commande",
  systemRole:"system_role"
  // ATTENTION : n'ajouter ici que des champs dont le nom JS diffère RÉELLEMENT
  // du nom de colonne. Chaque entrée est inversée dans FIELD_FROM_DB et
  // renomme donc aussi le champ à la RELECTURE. Les anciens alias employés
  // (contrat/dateDebut/salaire) faisaient disparaître salaire_brut,
  // type_contrat et date_embauche après chaque rechargement des données.
};
// Conversion générique camelCase → snake_case pour tous les autres champs
// (ex: tvaExo→tva_exo, prixAchat→prix_achat, stockActuel→stock_actuel...)
function camelToSnake(k){ return k.replace(/([A-Z])/g, (m)=>"_"+m.toLowerCase()); }
const FIELD_FROM_DB = Object.fromEntries(Object.entries(FIELD_TO_DB).map(([a,b])=>[b,a]));

function toDb(obj){
  const r={};
  for(const [k,v] of Object.entries(obj)){
    const dk = k==="system" ? "system_role" : (FIELD_TO_DB[k]||camelToSnake(k));
    if(dk==="updated_at") continue;
    // Convertir les timestamps epoch (Date.now()) en ISO string pour Postgres TIMESTAMPTZ
    if((dk==="created_at"||dk==="updated_at") && typeof v==="number"){
      r[dk]=new Date(v).toISOString();
    } else if(v===""){
      // Chaîne vide → null (un champ non sélectionné/vide envoyé tel quel fait échouer
      // Postgres sur les colonnes UUID et DATE : "invalid input syntax for type uuid/date")
      r[dk]=null;
    } else {
      r[dk]=v;
    }
  }
  delete r.updated_at;
  return r;
}
function fromDb(row){
  if(!row)return row;
  const r={};
  for(const [k,v] of Object.entries(row)){
    const ak=FIELD_FROM_DB[k]||k;
    r[ak]= v===null?undefined:v;
  }
  delete r.updated_at;
  return r;
}
function mapRows(rows){ return (rows||[]).map(fromDb); }

/* ============================================================
   COUCHE DB SUPABASE (CRUD)
   ============================================================ */
// Timeout sur chaque requête Supabase (20s max)
const DB_TIMEOUT_MS = 45000;
async function withTimeout(promise, ms=DB_TIMEOUT_MS, label=""){
  let timer;
  const timeout = new Promise((_,rej)=>{ timer=setTimeout(()=>rej(new Error(`Timeout ${label} (${ms/1000}s)`)), ms); });
  try { return await Promise.race([promise, timeout]); }
  finally { clearTimeout(timer); }
}

// PostgREST plafonne chaque réponse à 1000 lignes : sans pagination, toute table
// dépassant 1000 lignes (journal, mouvements de caisse...) était tronquée EN SILENCE.
// Renvoie null (et non []) en cas d'échec, pour que l'appelant conserve ses données
// en mémoire au lieu de les écraser par une liste vide.
const DB_PAGE = 1000;
async function dbFetch(table, order="created_at"){
  try {
    let all=[], tie=order!=="id";
    for(let from=0;;from+=DB_PAGE){
      let q=SB.from(table).select("*").order(order,{ascending:false});
      if(tie) q=q.order("id",{ascending:false}); // départage les ex-aequo entre pages
      let {data,error} = await withTimeout(q.range(from,from+DB_PAGE-1), DB_TIMEOUT_MS, table);
      if(error && tie){ // table sans colonne "id" : on retente sans le tri secondaire
        tie=false;
        ({data,error} = await withTimeout(SB.from(table).select("*").order(order,{ascending:false}).range(from,from+DB_PAGE-1), DB_TIMEOUT_MS, table));
      }
      if(error){ console.error("dbFetch",table,error); return null; }
      all=all.concat(data||[]);
      if(!data||data.length<DB_PAGE) break;
    }
    return mapRows(all);
  } catch(e){ console.warn("dbFetch timeout/error:",table,e.message); return null; }
}
async function dbFetchOne(table){
  try {
    const {data,error} = await withTimeout(SB.from(table).select("*").limit(1).maybeSingle(), DB_TIMEOUT_MS, table);
    if(error){ console.error("dbFetchOne",table,error); return false; }
    return fromDb(data);
  } catch(e){ console.warn("dbFetchOne timeout/error:",table,e.message); return false; }
}
// Rend lisible l'erreur renvoyée par Supabase : le message Postgres est la seule
// information qui permette d'identifier une colonne manquante ou un type invalide.
function errTxt(error){
  if(!error)return "erreur inconnue";
  const parts=[error.message,error.details,error.hint].filter(Boolean);
  let t=parts.join(" — ");
  if(error.code) t="["+error.code+"] "+t;
  return t.length>220?t.slice(0,220)+"…":t;
}

async function dbUpsert(table, obj){
  const row = toDb(obj);
  const {error} = await SB.from(table).upsert(row, {onConflict:"id"});
  if(error){ console.error("dbUpsert",table,error,row); toast("⚠ Sauvegarde refusée ("+table+") : "+errTxt(error), 9000); return false; }
  return true;
}
async function dbUpdate(table, id, patch){
  const row = toDb(patch);
  const {error} = await SB.from(table).update(row).eq("id",id);
  if(error){ console.error("dbUpdate",table,error); toast("⚠ Mise à jour refusée ("+table+") : "+errTxt(error), 9000); return false; }
  return true;
}
async function dbDelete(table, id){
  const {error} = await SB.from(table).delete().eq("id",id);
  if(error){ console.error("dbDelete",table,error); toast("⚠ Suppression refusée ("+table+") : "+errTxt(error), 9000); return false; }
  return true;
}
async function dbUpsertSettings(settings){
  const row = toDb({...settings});
  delete row.id;
  if(!DB._settingsId){ const r=await SB.from("app_settings").select("id").limit(1).maybeSingle(); DB._settingsId=r?.data?.id; }
  if(DB._settingsId){
    const {error}=await SB.from("app_settings").update(row).eq("id",DB._settingsId);
    if(error){ console.error("settings update",error); toast("⚠ Sauvegarde refusée (settings) : "+errTxt(error), 9000); return false; }
    return true;
  } else {
    const {data,error}=await SB.from("app_settings").insert(row).select("id").maybeSingle();
    if(error){ console.error("settings insert",error); toast("⚠ Sauvegarde refusée (settings) : "+errTxt(error), 9000); return false; }
    DB._settingsId=data?.id;
    return true;
  }
}

// Sync optimiste : met à jour l'état local PUIS sync Supabase en fond
async function sync(table, obj){
  const supaTable = {users:"crm_users", roles:"crm_roles", settings:"app_settings"}[table]||table;
  if(table==="settings"){ return await dbUpsertSettings(DB.settings).catch(e=>{console.error(e);return false;}); }
  return await dbUpsert(supaTable, obj).catch(e=>{console.error(e);return false;});
}
function syncDel(table, id){
  const supaTable = {users:"crm_users", roles:"crm_roles", "journal":"journal_entries"}[table]||table;
  dbDelete(supaTable, id).catch(e=>console.error(e));
}

/* ============================================================
   CHARGEMENT INITIAL
   ============================================================ */
async function loadAll(){
  // Phase 1 : tables critiques (login + navigation de base)
  const r1 = await Promise.allSettled([
    dbFetchOne("app_settings"),          // 0
    dbFetch("crm_roles","created_at"),   // 1
    dbFetch("crm_users","created_at"),   // 2
    dbFetch("clients","created_at"),     // 3
    dbFetch("products","designation"),   // 4
    dbFetch("fournisseurs","created_at"),// 5
    dbFetch("crm_caisses","created_at"), // 6
    dbFetch("crm_notifications","created_at"), // 7
  ]);
  const g1 = (i,def) => (r1[i].status==="fulfilled" && r1[i].value!=null && r1[i].value!==false) ? r1[i].value : def;
  // BUG CRITIQUE corrigé ici : settingsOk était utilisé (ligne settingsRow) avant
  // sa propre déclaration `const` plus bas -> ReferenceError "Cannot access
  // 'settingsOk' before initialization" à CHAQUE chargement, qui faisait échouer
  // loadAll() avant même d'atteindre DB.users -> DB.users restait vide en
  // permanence -> "Connexion Supabase impossible" pour tout le monde, à chaque
  // connexion, sans rapport avec Supabase lui-même.
  const settingsOk  = r1[0].status==="fulfilled" && r1[0].value!==false;
  const settingsRow = settingsOk ? r1[0].value : null;
  const rolesRows   = g1(1, []);
  const rolesOk     = r1[1].status==="fulfilled" && Array.isArray(r1[1].value);
  DB.users        = g1(2, DB.users||[]);
  DB.clients      = g1(3, DB.clients||[]);
  DB.products     = g1(4, DB.products||[]);
  DB.fournisseurs = g1(5, DB.fournisseurs||[]);
  DB.caisses      = g1(6, DB.caisses||[]);
  DB.notifications= g1(7, DB.notifications||[]);

  // Settings
  if(settingsRow){
    DB._settingsId = settingsRow.id;
    DB.settings = {
      company:     settingsRow.company    || defaultCompany(),
      tva:         settingsRow.tva        || 18,
      devise:      settingsRow.devise     || "F CFA",
      year:        settingsRow.year       || new Date().getFullYear(),
      seqDevis:    settingsRow.seq_devis  || settingsRow.seqDevis    || 1,
      seqFacture:  settingsRow.seq_facture|| settingsRow.seqFacture  || 1,
      seqCommande: settingsRow.seq_commande||settingsRow.seqCommande || 1,
      listes:      settingsRow.listes     || null,
    };
  } else if(settingsOk){
    // Aucune ligne en base (première installation) : on crée les paramètres par défaut.
    DB.settings = defaultSettings();
    dbUpsertSettings(DB.settings).catch(()=>{});
  } else if(!DB.settings || !DB.settings.company){
    // Échec réseau : on n'écrase SURTOUT PAS la base (compteurs de numérotation, infos société)
    DB.settings = defaultSettings();
  }

  // Auto-guérison : si le cachet/signature n'est pas en base (jamais uploadé, ou
  // effacé par un bug passé), on réinjecte le cachet officiel Creatis Studio et on
  // le persiste, pour que la page Paramètres reflète la réalité affichée sur les
  // documents imprimés.
  if(DB.settings.company && !DB.settings.company.signatureUrl){
    DB.settings.company.signatureUrl = CACHET_CREATIS_B64; // mémoire seulement : pas de réécriture en base
  }

  // Rôles
  if(rolesRows.length){
    DB.roles = rolesRows.map(r=>({...r, system: r.system_role||r.systemRole}));
  } else if(rolesOk){
    DB.roles = defaultRoles();
    DB.roles.forEach(r=>SB.from("crm_roles").upsert(toDb({...r,systemRole:r.system}),{onConflict:"id"}).then(()=>{},()=>{}));
  } else if(!DB.roles || !DB.roles.length){
    DB.roles = defaultRoles(); // échec réseau : valeurs par défaut en mémoire, sans écraser les rôles en base
  }

  // Phase 2 : reste des données (facturation, compta, RH, production...).
  // Attendue (await) elle aussi : avant, cette phase se lançait sans être
  // attendue par loadAll(), donc window.__loadAllPromise pouvait se résoudre
  // avant que devis/factures/commandes soient chargés -> tableau de bord
  // incomplet au premier affichage malgré l'attente faite dans doLogin().
  const r2 = await Promise.allSettled([
    dbFetch("devis","created_at"),        dbFetch("factures","created_at"),
    dbFetch("commandes","created_at"),    dbFetch("depenses","created_at"),
    dbFetch("crm_employes","created_at"), dbFetch("crm_conges","created_at"),
    dbFetch("crm_stock_mouvements","date"),dbFetch("crm_caisse_mvt","date"),
    dbFetch("crm_plan_comptable","compte"),dbFetch("journal_entries","date"),
    dbFetch("crm_prod_etapes","created_at"),dbFetch("crm_prod_activite","created_at"),
    dbFetch("crm_email_logs","created_at"),dbFetch("crm_bons_achat","created_at"),
    dbFetch("crm_bons_livraison","created_at"),dbFetch("crm_activite_infographiste","created_at"),
    dbFetch("crm_immobilisations","date_acquisition"),dbFetch("crm_dotations_amort","created_at"),
  ]);
  const g2=(i,k)=>{const v=r2[i].status==="fulfilled"?r2[i].value:null; return v!=null?v:(DB[k]||[]);};
  DB.devis=g2(0,"devis"); DB.factures=g2(1,"factures"); DB.commandes=g2(2,"commandes"); DB.depenses=g2(3,"depenses");
  DB.employes=g2(4,"employes"); DB.conges=g2(5,"conges"); DB.stockMvt=g2(6,"stockMvt"); DB.caisseMvt=g2(7,"caisseMvt");
  DB.planCompta=g2(8,"planCompta"); DB.journal=g2(9,"journal"); DB.prodEtapes=g2(10,"prodEtapes"); DB.prodActivite=g2(11,"prodActivite");
  DB.emailLogs=g2(12,"emailLogs"); DB.bonsAchat=g2(13,"bonsAchat"); DB.bonsLivraison=g2(14,"bonsLivraison"); DB.activiteInfo=g2(15,"activiteInfo");
  DB.immobilisations=g2(16,"immobilisations"); DB.dotationsAmort=g2(17,"dotationsAmort");
  DB._lastRefresh=Date.now();
  if(typeof refreshBadges==="function") refreshBadges();
}



