async function doLogin(){
  const login=($("#li-login")||{}).value?.trim().toLowerCase()||"";
  const pw=($("#li-pwd")||{}).value||"";
  const errEl=$("#login-err");
  // Les données peuvent encore être en train de charger en arrière-plan quand on
  // clique "Se connecter" juste après l'ouverture de l'app — même si DB.users est
  // déjà rempli, d'autres données du tableau de bord (factures, devis, caisse...)
  // peuvent ne pas l'être encore. On attend TOUJOURS la fin du chargement en cours
  // (immédiat si déjà terminé) avant d'entrer dans l'app, pour ne jamais afficher
  // un tableau de bord partiellement vide qui obligerait à recharger la page.
  if(window.__loadAllPromise){
    if(!DB.users||!DB.users.length){
      if(errEl)errEl.textContent="Chargement en cours, veuillez patienter…";
    }
    try{ await Promise.race([window.__loadAllPromise, new Promise(r=>setTimeout(r,8000))]); }catch(e){}
  }
  if(!DB.users||!DB.users.length){
    if(errEl)errEl.textContent="Connexion Supabase impossible. Vérifiez config.js et rechargez.";return;
  }
  const u=DB.users.find(x=>(x.login||"").toLowerCase()===login&&x.active!==false);
  if(!u){if(errEl)errEl.textContent="Identifiant ou mot de passe incorrect.";return}
  const h=await passHash(u.login,pw);
  if(u.pass!==h){if(errEl)errEl.textContent="Identifiant ou mot de passe incorrect.";return}
  // Vérifier si l'utilisateur a un rôle assigné
  if(!(u.roleId||u.role_id)){
    if(errEl)errEl.textContent="⚠️ Votre compte est actif mais aucun rôle n'a encore été assigné. Contactez l'administrateur.";return;
  }
  enterApp(u);
}
function enterApp(u){
  USER=u;
  try{localStorage.setItem(SESSION_KEY,u.id)}catch(e){}
  // Annuler le timer + retirer l'écran de chargement initial
  if(typeof window._clearBootTimer==="function") window._clearBootTimer();
  const _init=document.getElementById("_init_screen"); if(_init) _init.remove();
  document.body.classList.remove("auth-on");
  $("#auth").classList.remove("show");
  applyNav();refreshUserChip();refreshBadges();go(firstAllowedRoute());
  startAutoRefresh();
}

// Actualisation manuelle : recharge toutes les données depuis la base
// (voir les modifications faites par les autres utilisateurs) et rafraîchit la vue actuelle
async function refreshAllData(silent){
  const icon=document.getElementById("refresh-icon");
  if(icon) icon.classList.add("spinning");
  try{
    await loadAll();
    if(current) go(current);
    refreshBadges();
    if(!silent) toast("✅ Données actualisées");
  }catch(e){
    console.error("refreshAllData:",e);
    if(!silent) toast("⚠️ Échec de l'actualisation");
  }finally{
    if(icon) setTimeout(()=>icon.classList.remove("spinning"),300);
  }
}

// Rafraîchissement automatique périodique, pour que les modifications faites
// par d'autres utilisateurs apparaissent sans recharger la page manuellement.
//
// Ne recharge QUE les tables "volatiles" (celles qui changent en cours de
// journée), pas les 22 tables de loadAll(). Les tables de référence — rôles,
// comptes utilisateurs, catalogue produits, fournisseurs, plan comptable,
// immobilisations/dotations, paramètres société — changent rarement en cours
// de journée ; les re-télécharger en entier toutes les quelques minutes pour
// chaque onglet ouvert (avant : 3 min, sans distinction de table) était le
// principal poste de consommation de bande passante Supabase, qui grossit en
// plus avec le temps à mesure que les tables s'allongent. Ces tables restent
// à jour à la prochaine connexion/rechargement, ou via "Actualiser" manuel
// (qui, lui, recharge toujours tout via refreshAllData/loadAll()).
async function refreshVolatileData(silent){
  const icon=document.getElementById("refresh-icon");
  if(icon) icon.classList.add("spinning");
  try{
    const r=await Promise.allSettled([
      dbFetch("clients","created_at"),      dbFetch("crm_caisses","created_at"),
      dbFetch("crm_notifications","created_at"), dbFetch("devis","created_at"),
      dbFetch("factures","created_at"),     dbFetch("commandes","created_at"),
      dbFetch("depenses","created_at"),     dbFetch("crm_employes","created_at"),
      dbFetch("crm_conges","created_at"),   dbFetch("crm_stock_mouvements","date"),
      dbFetch("crm_caisse_mvt","date"),     dbFetch("journal_entries","date"),
      dbFetch("crm_prod_etapes","created_at"),dbFetch("crm_prod_activite","created_at"),
      dbFetch("crm_email_logs","created_at"),dbFetch("crm_bons_achat","created_at"),
      dbFetch("crm_bons_livraison","created_at"),dbFetch("crm_activite_infographiste","created_at"),
    ]);
    const g=(i,k)=>{const v=r[i].status==="fulfilled"?r[i].value:null; return v!=null?v:(DB[k]||[]);};
    DB.clients=g(0,"clients"); DB.caisses=g(1,"caisses"); DB.notifications=g(2,"notifications"); DB.devis=g(3,"devis");
    DB.factures=g(4,"factures"); DB.commandes=g(5,"commandes"); DB.depenses=g(6,"depenses"); DB.employes=g(7,"employes");
    DB.conges=g(8,"conges"); DB.stockMvt=g(9,"stockMvt"); DB.caisseMvt=g(10,"caisseMvt"); DB.journal=g(11,"journal");
    DB.prodEtapes=g(12,"prodEtapes"); DB.prodActivite=g(13,"prodActivite"); DB.emailLogs=g(14,"emailLogs");
    DB.bonsAchat=g(15,"bonsAchat"); DB.bonsLivraison=g(16,"bonsLivraison"); DB.activiteInfo=g(17,"activiteInfo");
    DB._lastRefresh=Date.now();
    if(current) go(current);
    refreshBadges();
    if(!silent) toast("✅ Données actualisées");
  }catch(e){
    console.error("refreshVolatileData:",e);
    if(!silent) toast("⚠️ Échec de l'actualisation");
  }finally{
    if(icon) setTimeout(()=>icon.classList.remove("spinning"),300);
  }
}
function startAutoRefresh(){
  if(window.__autoRefreshInt) clearInterval(window.__autoRefreshInt);
  const STALE=10*60*1000;
  // Un onglet caché/en veille ne télécharge plus rien ; au retour, on rattrape si les données ont > 10 min.
  window.__autoRefreshInt=setInterval(()=>{
    if(USER && !document.hidden) refreshVolatileData(true);
  }, STALE);
  if(!window.__visRefreshBound){
    window.__visRefreshBound=true;
    document.addEventListener("visibilitychange",()=>{
      if(!document.hidden && USER && Date.now()-(DB._lastRefresh||0)>STALE) refreshVolatileData(true);
    });
  }
}
