const $=s=>document.querySelector(s);
function fcfa(n){n=Math.round(n||0);return n.toLocaleString("fr-FR").replace(/\u202f/g," ")+" F"}
function fcfaPlain(n){n=Math.round(n||0);if(n>=1000000)return (n/1000000).toFixed(1).replace(".",",")+"M";if(n>=1000)return(n/1000).toFixed(0)+"k";return n+""}

/* ===== Montant en toutes lettres (français) ===== */
function nombreEnLettres(n){
  n=Math.floor(Math.abs(+n||0));
  if(!n)return "zéro";
  const U=["","un","deux","trois","quatre","cinq","six","sept","huit","neuf","dix","onze","douze","treize","quatorze","quinze","seize","dix-sept","dix-huit","dix-neuf"];
  const D=["","","vingt","trente","quarante","cinquante","soixante","soixante","quatre-vingt","quatre-vingt"];
  // final=false  ->  pas de « s » sur vingt/cent (invariables devant « mille »)
  function dizaine(x,final){
    if(x<20)return U[x];
    const d=Math.floor(x/10),u=x%10;
    if(d===7)return u===1?"soixante et onze":(u?"soixante-"+U[10+u]:"soixante-dix");
    if(d===9)return "quatre-vingt-"+U[10+u];
    if(d===8)return u?"quatre-vingt-"+U[u]:(final?"quatre-vingts":"quatre-vingt");
    if(!u)return D[d];
    return u===1?D[d]+" et un":D[d]+"-"+U[u];
  }
  function centaine(x,final){
    const c=Math.floor(x/100),r=x%100;let s="";
    if(c)s=(c>1?U[c]+" ":"")+"cent"+((c>1&&!r&&final)?"s":"");
    if(r)s=(s?s+" ":"")+dizaine(r,final);
    return s;
  }
  const out=[];let reste=n;
  [[1e9,"milliard"],[1e6,"million"]].forEach(function(p){
    const q=Math.floor(reste/p[0]);
    if(q){out.push(centaine(q,true)+" "+p[1]+(q>1?"s":""));reste=reste%p[0];}
  });
  const mil=Math.floor(reste/1000);
  if(mil){out.push(mil===1?"mille":centaine(mil,false)+" mille");reste=reste%1000;}
  if(reste)out.push(centaine(reste,true));
  return out.join(" ").replace(/\s+/g," ").trim();
}
function deviseEnLettres(dev,n){
  const d=String(dev||"F CFA").toUpperCase(),s=Math.floor(Math.abs(+n||0))<2;
  if(d.includes("CFA"))return s?"franc CFA":"francs CFA";
  if(d.includes("EUR")||d.includes("€"))return s?"euro":"euros";
  if(d.includes("USD")||d.includes("$"))return s?"dollar US":"dollars US";
  return String(dev||"");
}
function montantEnLettres(n,dev){
  const m=nombreEnLettres(n);
  return m.charAt(0).toUpperCase()+m.slice(1)+" "+deviseEnLettres(dev,n);
}
