  const totalEmp=employes.length;
  const actifs=employes.filter(e=>statutEmp(e)==="actif").length;
  const stagiaires=employes.filter(e=>statutEmp(e)==="stagiaire"||(e.type_contrat||e.contrat||"")==="Stage").length;

  // Breadcrumb
