function greetingBanner(){
  const now=new Date();
  const h=now.getHours();
  const firstName=(USER&&USER.name||"").split(" ")[0]||"";
  let salut="Bonjour", icon="☀️";
  if(h>=18&&h<22){ salut="Bonsoir"; icon="🌆"; }
  else if(h>=22||h<5){ salut="Bonne nuit"; icon="🌙"; }
  else if(h<12){ icon="🌅"; }

  const dateStr=now.toLocaleDateString("fr-FR",{weekday:"long",day:"numeric",month:"long",year:"numeric"});
  const dateCap=dateStr.charAt(0).toUpperCase()+dateStr.slice(1);

  const dayIdx=Math.floor((now-new Date(now.getFullYear(),0,0))/86400000);
  const quote=MOTIVATION_QUOTES[dayIdx % MOTIVATION_QUOTES.length];

  return `<div class="card panel" style="margin-bottom:16px;background:linear-gradient(135deg,var(--carte) 55%,var(--cyan)07);display:flex;align-items:center;justify-content:space-between;gap:20px;flex-wrap:wrap">
    <div style="flex:1;min-width:220px">
      <div style="font-size:19px;font-weight:700;display:flex;align-items:center;gap:8px">
        <span>${icon}</span> ${salut}${firstName?", "+esc(firstName):""}
      </div>
      <div style="font-size:12.5px;color:var(--txt-2);margin-top:2px">${esc(dateCap)}</div>
      <div style="font-size:12.5px;color:var(--txt-2);font-style:italic;margin-top:10px;max-width:440px;line-height:1.5">💬 ${esc(quote)}</div>
    </div>
    <div style="display:flex;align-items:center;gap:18px">
      <div style="text-align:center">
        <div id="greet-clock-time" class="tabnum" style="font-size:28px;font-weight:700;letter-spacing:.02em;color:var(--cyan)">--:--:--</div>
        <div style="font-size:10.5px;color:var(--txt-2);text-transform:uppercase;letter-spacing:.06em">Heure locale</div>
      </div>
      <div id="greet-weather" style="text-align:center;min-width:76px;border-left:1px solid var(--ligne);padding-left:18px">
        <div style="font-size:22px">🌤️</div>
        <div style="font-size:11px;color:var(--txt-2)">…</div>
      </div>
    </div>
  </div>`;
}

const WEATHER_ICONS={
  0:["☀️","Ciel clair"],1:["🌤️","Peu nuageux"],2:["⛅","Partiellement nuageux"],3:["☁️","Couvert"],
  45:["🌫️","Brouillard"],48:["🌫️","Brouillard givrant"],
  51:["🌦️","Bruine légère"],53:["🌦️","Bruine"],55:["🌦️","Bruine forte"],
  61:["🌧️","Pluie légère"],63:["🌧️","Pluie"],65:["🌧️","Pluie forte"],
  80:["🌧️","Averses"],81:["🌧️","Averses"],82:["⛈️","Averses violentes"],
  95:["⛈️","Orage"],96:["⛈️","Orage + grêle"],99:["⛈️","Orage violent"],
};

function initGreetingWidgets(){
  if(window.__clockInt) clearInterval(window.__clockInt);
  const tick=()=>{
    if(current!=="dashboard"){ clearInterval(window.__clockInt); return; }
    const el=document.getElementById("greet-clock-time");
    if(!el){ clearInterval(window.__clockInt); return; }
    el.textContent=new Date().toLocaleTimeString("fr-FR");
  };
  tick();
  window.__clockInt=setInterval(tick,1000);
  fetchAbidjanWeather();
}

async function fetchAbidjanWeather(){
  const cache=window.__weatherCache, now=Date.now();
  if(cache && (now-cache.ts)<20*60*1000){ renderWeather(cache.temp,cache.code); return; }
  try{
    const res=await fetch("https://api.open-meteo.com/v1/forecast?latitude=5.36&longitude=-4.0083&current_weather=true&timezone=Africa%2FAbidjan");
    const data=await res.json();
    const cw=data&&data.current_weather;
    if(cw){
      window.__weatherCache={temp:cw.temperature,code:cw.weathercode,ts:now};
      renderWeather(cw.temperature,cw.weathercode);
    }
  }catch(e){ console.warn("Météo indisponible",e); }
}
function renderWeather(temp,code){
  const el=document.getElementById("greet-weather");
  if(!el) return;
  const entry=WEATHER_ICONS[code]||["🌤️","—"];
  el.innerHTML=`<div style="font-size:22px">${entry[0]}</div><div style="font-size:15px;font-weight:700">${Math.round(temp)}°C</div><div style="font-size:10px;color:var(--txt-2)">${esc(entry[1])}</div>`;
}

/* ============================================================
   NOTIFICATIONS — Admin → équipe (message ciblé ou diffusion)
   ============================================================ */
function notifsForCurrentUser(){
  const all = Array.isArray(DB.notifications) ? DB.notifications : [];
  const uid = USER && USER.id;
  return all.filter(n=>{
    const dest = n.destinataireId || n.destinataire_id || null;
    const cible = !dest || dest===uid; // null = diffusion à tous
    if(!cible) return false;
    const lu = Array.isArray(n.luPar||n.lu_par) ? (n.luPar||n.lu_par) : [];
    return !lu.includes(uid);
  }).sort((a,b)=>(b.createdAt||b.created_at||"").localeCompare(a.createdAt||a.created_at||""));
}

function notifBanner(){
  const notifs = notifsForCurrentUser();
  const canSend = isAdmin();
  if(!notifs.length && !canSend) return "";

  const TYPE_STYLE = {
    info:    ["#00AEEF","ℹ️"],
    warning: ["#FFC400","⚠️"],
    urgent:  ["#EC008C","🚨"],
  };

  const items = notifs.map(n=>{
    const [col,ic] = TYPE_STYLE[n.type]||TYPE_STYLE.info;
    const auteur = (DB.users||[]).find(u=>u.id===(n.auteurId||n.auteur_id));
    const isBroadcast = !(n.destinataireId||n.destinataire_id);
    return `<div style="display:flex;gap:10px;align-items:flex-start;padding:11px 14px;border-radius:10px;background:${col}0c;border-left:3px solid ${col};margin-bottom:8px">
      <span style="font-size:16px;flex-shrink:0">${ic}</span>
      <div style="flex:1;min-width:0">
        <div style="font-weight:700;font-size:13px">${esc(n.titre||"")}</div>
        <div style="font-size:12.5px;color:var(--txt-2);margin-top:2px;line-height:1.5">${esc(n.message||"")}</div>
        <div style="font-size:10.5px;color:var(--txt-2);margin-top:6px">${esc(auteur?.name||"Administrateur")} · ${isBroadcast?"À toute l'équipe":"Message direct"}</div>
      </div>
      <button onclick="markNotifLu('${n.id}')" title="Marquer comme lu" style="border:none;background:none;cursor:pointer;color:var(--txt-2);font-size:16px;flex-shrink:0;padding:2px">✕</button>
    </div>`;
  }).join("");

  const sendBtn = canSend ? `<span class="linkish" style="font-size:11.5px" onclick="sendNotificationModal()">📢 ${notifs.length?"Envoyer un autre message":"Envoyer un message à l'équipe"}</span>` : "";

  return `<div style="margin-bottom:16px">
    ${notifs.length ? `<div style="font-size:11px;font-weight:700;color:var(--txt-2);text-transform:uppercase;letter-spacing:.06em;margin-bottom:8px;display:flex;justify-content:space-between;align-items:center">
      <span>🔔 ${notifs.length} message${notifs.length>1?"s":""}</span>${sendBtn}
    </div>${items}` : (canSend ? `<div style="text-align:right">${sendBtn}</div>` : "")}
  </div>`;
}

async function markNotifLu(id){
  const n = (DB.notifications||[]).find(x=>x.id===id);
  if(!n) return;
  const uid = USER && USER.id;
  const lu = Array.isArray(n.luPar||n.lu_par) ? [...(n.luPar||n.lu_par)] : [];
  if(!lu.includes(uid)) lu.push(uid);
  n.luPar = lu;
  await dbUpdate("crm_notifications", id, {lu_par:lu});
  if(current==="dashboard") viewDashboard();
}

