/* ============================================================
   ITS — IMPÔT SUR LES TRAITEMENTS ET SALAIRES (Côte d'Ivoire)
   ------------------------------------------------------------
   Barème progressif mensuel et Réduction d'Impôt pour Charges de
   Famille (RICF), repris de la brochure DGI « Impôts et taxes en
   Côte d'Ivoire » (art. 119 bis et 120 du CGI).
       ITS dû = IB (barème progressif) − RICF, plancher à zéro.
   ============================================================ */
const ITS_TRANCHES=[
  {jusqua:      75000, taux:0.00},
  {jusqua:     240000, taux:0.16},
  {jusqua:     800000, taux:0.21},
  {jusqua:    2400000, taux:0.24},
  {jusqua:    8000000, taux:0.28},
  {jusqua:   Infinity, taux:0.32}
];
const ITS_RICF={1:0, 1.5:5500, 2:11000, 2.5:16500, 3:22000, 3.5:27500, 4:33000, 4.5:38500, 5:44000};
const CNPS_TAUX_SALARIAL=0.063;
const CNPS_TAUX_PATRONAL=0.1645;

// ASSIETTE — la brochure DGI donne le barème mais pas la composition de
// l'assiette (art. 118 du CGI). On retient ici le brut diminué de la part
// salariale CNPS. À faire confirmer par le comptable : si l'assiette est
// le brut lui-même, passer cette constante à false, rien d'autre à changer.
const ITS_ASSIETTE_DEDUIT_CNPS=true;

// Impôt brut : application tranche par tranche (barème progressif)
function calcITSBrut(base){
  base=Math.max(0,Math.round(+base||0));
  let bas=0, ib=0; const detail=[];
  for(const t of ITS_TRANCHES){
    const assiette=Math.max(0,Math.min(base,t.jusqua)-bas);
    if(assiette>0){
      const montant=assiette*t.taux;
      ib+=montant;
      detail.push({de:bas,a:t.jusqua,assiette,taux:t.taux,montant:Math.round(montant)});
    }
    bas=t.jusqua;
    if(base<=bas)break;
  }
  return {ib:Math.round(ib),detail};
}

// Parts fiscales : 1 (célibataire) ou 2 (marié), + 0,5 par enfant, plafond 5
function partsFiscales(e){
  const sit=String((e&&(e.situation_matrimoniale||e.situationMatrimoniale))||"").toLowerCase();
  const socle=sit.startsWith("mari")?2:1;
  const enf=Math.max(0,+((e&&(e.nb_enfants!==undefined?e.nb_enfants:e.nbEnfants))||0));
  return Math.min(5, socle+0.5*enf);
}
function ricfMensuelle(parts){
  const p=Math.min(5,Math.max(1,Math.round((+parts||1)*2)/2));
  return ITS_RICF[p]!==undefined?ITS_RICF[p]:0;
}
function calcITS(base,parts){
  const r=calcITSBrut(base);
  const ricf=ricfMensuelle(parts);
  return {base:Math.max(0,Math.round(+base||0)), ib:r.ib, ricf, its:Math.max(0,r.ib-ricf), detail:r.detail};
}

// Décomposition complète brut -> net
function netDepuisBrut(brut,parts){
  brut=Math.max(0,Math.round(+brut||0));
  const cnps=Math.round(brut*CNPS_TAUX_SALARIAL);
  const base=ITS_ASSIETTE_DEDUIT_CNPS?Math.max(0,brut-cnps):brut;
  const t=calcITS(base,parts);
  return {brut, cnps, base, ib:t.ib, ricf:t.ricf, its:t.its, net:brut-cnps-t.its, detail:t.detail};
}

// Inversion net -> brut. net(brut) est croissante : dichotomie exacte,
// aucune formule approchée n'est utilisée.
function brutDepuisNet(netCible,parts){
  const cible=Math.max(0,Math.round(+netCible||0));
  if(!cible)return 0;
  let lo=cible, hi=Math.max(cible*2,cible+100000), garde=0;
  while(netDepuisBrut(hi,parts).net<cible && garde++<50) hi*=2;
  while(lo<hi){
    const mid=Math.floor((lo+hi)/2);
    if(netDepuisBrut(mid,parts).net<cible) lo=mid+1; else hi=mid;
  }
  return lo;
}

