function viewUsers(){
  if(!isAdmin()){$("#view").innerHTML=`<div class="card panel"><div class="empty"><h4>Accès réservé</h4><div>Cette section est réservée aux administrateurs.</div></div></div>`;return}
  if(usersTab==="comptes")
    $("#pg-actions").innerHTML=`<button class="btn btn-primary" onclick="editUser()"><svg width="16" height="16" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2.2"><path d="M12 5v14M5 12h14"/></svg>Nouveau compte</button>`;
  else if(usersTab==="roles")
    $("#pg-actions").innerHTML=`<button class="btn btn-primary" onclick="editRole()"><svg width="16" height="16" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2.2"><path d="M12 5v14M5 12h14"/></svg>Nouveau rôle</button>`;
  else
    $("#pg-actions").innerHTML=`<button class="btn" onclick="resetListes()" style="border-color:var(--warn);color:var(--warn)">↺ Réinitialiser</button>`;
  $("#view").innerHTML=`<div class="tabs">
    <button class="${usersTab==="comptes"?"active":""}" onclick="usersTab='comptes';viewUsers()">Comptes</button>
    <button class="${usersTab==="roles"?"active":""}" onclick="usersTab='roles';viewUsers()">Rôles & droits</button>
    <button class="${usersTab==="parametres"?"active":""}" onclick="usersTab='parametres';viewUsers()">⚙️ Paramètres</button>
  </div><div id="users-body"></div>`;
  if(usersTab==="comptes") $("#users-body").innerHTML=usersTable();
  else if(usersTab==="roles") $("#users-body").innerHTML=rolesTable();
  else parametresTable();
}
function usersTable(){
  if(!DB.users.length)return emptyState("Aucun compte","Créez les comptes de votre équipe.","Nouveau compte","editUser()");
  return`<div class="card"><div style="overflow-x:auto"><table><thead><tr><th>Utilisateur</th><th>Identifiant</th><th>Rôle</th><th>Statut</th><th>Caisse</th><th></th></tr></thead><tbody>${DB.users.map(u=>{const r=roleOf(u);return`<tr><td><div class="nm">${esc(u.name)}</div>${u.id===USER.id?'<div class="meta">vous</div>':''}</td><td class="meta tabnum">${esc(u.login)}</td><td>${r?`<span class="rdot cc-${r.color||"noir"}"></span>${esc(r.name)}`:`<span class="pill" style="background:#fff3cd;color:#856404;border:1px solid #ffc107;font-size:10px">⚠️ Sans rôle</span>`}</td><td>${u.active===false?'<span class="pill p-grey"><span class="dot"></span>Inactif</span>':'<span class="pill p-green"><span class="dot"></span>Actif</span>'}</td><td>${(()=>{const c=(DB.caisses||[]).find(x=>x.id===(u.caisseId||u.caisse_id));return c?`<span style="padding:2px 8px;border-radius:10px;font-size:10px;font-weight:600;background:${c.couleur||"#00AEEF"}20;color:${c.couleur||"#00AEEF"};border:1px solid ${c.couleur||"#00AEEF"}40">${esc(c.nom)}</span>`:"<span class=\"meta\">—</span>";})()}</td><td class="r"><button class="btn btn-sm btn-ghost" onclick="editUser('${u.id}')">Modifier</button></td></tr>`}).join("")}</tbody></table></div></div>`;
}
function rolesTable(){
  const rows=DB.roles.map(r=>{
    const users=(DB.users||[]).filter(u=>(u.roleId||u.role_id)===r.id);
    const mods=(MODS||[]).filter(m=>r.perms&&r.perms[m.k]&&r.perms[m.k]!=="none").length;
    const usersHtml=users.length
      ? users.map(u=>`<span style="display:inline-flex;align-items:center;gap:4px;padding:2px 8px 2px 4px;border-radius:10px;font-size:11px;font-weight:600;background:var(--papier);margin:2px"><span class="rdot cc-${r.color||"noir"}"></span>${esc(u.name)}</span>`).join("")
      : `<span style="color:var(--txt-3);font-size:11px;font-style:italic">Aucun utilisateur</span>`;
    return `<tr>
      <td><span class="rdot cc-${r.color||"noir"}"></span><span class="nm">${esc(r.name)}</span>${r.system?' <span class="seg">système</span>':""}</td>
      <td class="meta">${mods} module(s)</td>
      <td>${usersHtml}</td>
      <td class="r"><button class="btn btn-sm btn-ghost" onclick="editRole('${r.id}')">Configurer</button></td>
    </tr>`;
  }).join("");
  return `<div class="card"><div style="overflow-x:auto"><table>
    <thead><tr><th>Rôle</th><th>Accès</th><th>Utilisateurs assignés</th><th></th></tr></thead>
    <tbody>${rows}</tbody>
  </table></div></div>`;
}

function editUser(id){
  const u=id?DB.users.find(x=>x.id===id):{active:true,roleId:(DB.roles[0]||{}).id,name:"",login:""};
  drawer(id?"Modifier le compte":"Nouveau compte","Utilisateur",`<form id="f-user" autocomplete="off">
    <input type="text" name="fake-user" autocomplete="username" style="position:absolute;left:-9999px;width:1px;height:1px" tabindex="-1" aria-hidden="true">
    <input type="password" name="fake-pass" autocomplete="new-password" style="position:absolute;left:-9999px;width:1px;height:1px" tabindex="-1" aria-hidden="true">
    <div class="field"><label>Nom complet *</label><input name="name" value="${esc(u.name)}" autocomplete="off" required></div>
    <div class="row2"><div class="field"><label>Identifiant *</label><input name="login" value="${esc(u.login)}" autocomplete="off" required></div>
    <div class="field"><label>Rôle</label><select name="roleId">${DB.roles.map(r=>`<option value="${r.id}" ${(u.roleId||u.role_id)===r.id?"selected":""}>${esc(r.name)}</option>`).join("")}</select></div></div>
    <div class="field"><label>${id?"Nouveau mot de passe (vide = inchangé)":"Mot de passe *"}</label><input name="pwd" type="password" autocomplete="new-password"></div>
    <div class="field"><label>Caisse assignée</label>
      <select name="caisseId">
        <option value="">— Aucune caisse assignée —</option>
        ${(DB.caisses||[]).filter(c=>c.statut==="active").map(c=>`<option value="${c.id}" ${(u.caisseId||u.caisse_id)===c.id?"selected":""}>${esc(c.nom||"")}</option>`).join("")}
      </select>
      <div style="font-size:10.5px;color:var(--txt-2);margin-top:3px">Caisse par défaut lors des mouvements</div>
    </div>
    <div class="field"><label>Statut</label><select name="active"><option value="1" ${u.active!==false?"selected":""}>Actif</option><option value="0" ${u.active===false?"selected":""}>Inactif</option></select></div>
  </form>`,
  [(id&&u.id!==USER.id)?{label:"Supprimer",cls:"btn-danger",fn:`delUser('${id}')`}:null,{label:id?"💾 Enregistrer":"Créer le compte",cls:"btn-primary",fn:`saveUser('${id||""}')`}].filter(Boolean));
}
function adminCount(){return DB.users.filter(u=>(u.roleId||u.role_id)==="administrateur"&&u.active!==false).length}
async function saveUser(id){
  const f=$("#f-user");const fd=new FormData(f);
  const name=fd.get("name")?.trim()||"";const login=fd.get("login")?.trim()||"";
  if(!name||!login){toast("Nom et identifiant obligatoires");return}
  if(DB.users.some(x=>x.id!==id&&(x.login||"").toLowerCase()===login.toLowerCase())){toast("Cet identifiant existe déjà");return}
  const active=fd.get("active")==="1";const pw=fd.get("pwd")||"";
  if(id){
    const u=DB.users.find(x=>x.id===id);
    if((u.roleId||u.role_id)==="administrateur"&&(fd.get("roleId")!=="administrateur"||!active)&&adminCount()<=1){toast("Au moins un administrateur actif requis");return}
    u.name=name;u.login=login;u.roleId=fd.get("roleId");u.role_id=fd.get("roleId");u.active=active;
    if(pw)u.pass=await passHash(login,pw);
    if(u.id===USER.id){USER=u;refreshUserChip();applyNav()}
    sync("users",u);
  } else {
    if(!pw){toast("Mot de passe obligatoire");return}
    const u={id:uid(),name,login,roleId:fd.get("roleId"),role_id:fd.get("roleId"),active,pass:await passHash(login,pw),createdAt:Date.now()};
    DB.users.push(u);sync("users",u);
  }
  closeOverlays();toast(id?"Compte mis à jour":"Compte créé");go(window._userReturnTo||"users");window._userReturnTo=null;
}
function delUser(id){
  if(id===USER.id){toast("Vous ne pouvez pas supprimer votre propre compte");return}
  const u=DB.users.find(x=>x.id===id);if((u.roleId||u.role_id)==="administrateur"&&adminCount()<=1){toast("Au moins un administrateur requis");return}
  const _ret=window._userReturnTo||"users";confirmModal("Supprimer ce compte ?","",()=>{DB.users=DB.users.filter(x=>x.id!==id);syncDel("users",id);closeOverlays();toast("Compte supprimé");window._userReturnTo=null;go(_ret)});
}

