/* ── CRUD listes ─────────────────────────────────────────── */

function getListes(){
  return DB.settings.listes || {};
}

function addListe(key){
  const inp = document.getElementById("add-"+key);
  if(!inp) return;
  const val = inp.value.trim();
  if(!val){inp.focus();return;}
  const listes = getListes();
  const current = listes[key] || [...(LISTES_DEFAULTS[key]||[])];
  if(current.includes(val)){toast("Valeur déjà présente");inp.select();return;}
  current.push(val);
  saveListe(key, current);
  inp.value = "";
  inp.focus();
  // Ajouter le chip sans re-render
  const container = document.getElementById("liste-chips-"+key);
  if(container){
    const meta = LISTES_META.find(m=>m.key===key)||{color:"var(--cyan)"};
    const i = current.length-1;
    const chip = document.createElement("span");
    chip.style.cssText = `display:inline-flex;align-items:center;gap:4px;padding:4px 10px 4px 12px;border-radius:20px;font-size:12px;font-weight:600;background:${meta.color}15;border:1.5px solid ${meta.color}40;color:var(--encre)`;
    chip.innerHTML = `${esc(val)}<button onclick="removeListe('${key}',${i})" style="background:none;border:none;cursor:pointer;color:var(--txt-3);font-size:14px;line-height:1;padding:0 0 0 2px;display:flex;align-items:center" title="Supprimer">×</button>`;
    // Insérer avant le champ de saisie
    const addSpan = container.querySelector("span:last-child");
    if(addSpan) container.insertBefore(chip, addSpan);
    else container.appendChild(chip);
  }
}

function removeListe(key, index){
  const listes = getListes();
  const current = listes[key] || [...(LISTES_DEFAULTS[key]||[])];
  if(current.length <= 1){toast("Au moins 1 valeur requise");return;}
  current.splice(index, 1);
  saveListe(key, current);
  // Re-render juste cette liste
  parametresTable();
}

async function saveListe(key, items){
  if(!DB.settings.listes) DB.settings.listes = {};
  DB.settings.listes[key] = items;
  await sync("settings", DB.settings);
  toast(`✅ Liste "${LISTES_META.find(m=>m.key===key)?.label||key}" mise à jour`);
}

function resetListe(key){
  confirmModal(`Réinitialiser "${LISTES_META.find(m=>m.key===key)?.label||key}" ?`,
    "Les valeurs par défaut seront restaurées.",
    async ()=>{
      if(DB.settings.listes) delete DB.settings.listes[key];
      await sync("settings", DB.settings);
      toast("✅ Liste réinitialisée");
      parametresTable();
    }
  );
}

function resetListes(){
  confirmModal("Réinitialiser toutes les listes ?",
    "Toutes les personnalisations seront perdues.",
    async ()=>{
      DB.settings.listes = {};
      await sync("settings", DB.settings);
      toast("✅ Toutes les listes réinitialisées");
      viewUsers();
    }
  );
}

async function saveSociete(){
  const gv = id => document.getElementById(id)?.value?.trim()||"";
  const gn = id => +document.getElementById(id)?.value||0;
  // Relit la signature actuelle en base avant d'écraser "company" : si cet onglet
  // est resté ouvert depuis un moment, sa copie mémoire de signatureUrl peut être
  // périmée. Sans ça, enregistrer une simple modification (téléphone, adresse...)
  // effaçait silencieusement la signature en réécrivant une ancienne valeur vide.
  let currentSignature = DB.settings.company?.signatureUrl||"";
  try{
    const {data} = await SB.from("app_settings").select("company").limit(1).maybeSingle();
    if(data?.company?.signatureUrl) currentSignature = data.company.signatureUrl;
  }catch(e){ console.warn("Relecture signature avant sauvegarde échouée, valeur locale conservée",e); }
  DB.settings.company = {
    name:    gv("co-name"),
    activite:gv("co-activite"),
    siege:   gv("co-siege"),
    tel:     gv("co-tel"),
    email:   gv("co-email"),
    site:    gv("co-site"),
    rc:      gv("co-rc"),
    cc:      gv("co-cc"),
    centre:  gv("co-centre"),
    regime:  gv("co-regime"),
    banque:  gv("co-banque"),
    signatureUrl: currentSignature,
  };
  DB.settings.devise = gv("co-devise") || "F CFA";
  DB.settings.tva    = gn("co-tva") || 18;
  DB.settings.year   = gn("co-year") || new Date().getFullYear();
  await sync("settings", DB.settings);
  toast("✅ Informations société enregistrées");
}

// Upload signature : converti en base64, appliqué immédiatement (pas besoin de cliquer Enregistrer)
function handleSignatureUpload(input){
  const file=input.files&&input.files[0];
  if(!file) return;
  if(file.size>1500000){toast("Image trop lourde (max ~1.5 Mo)");return;}
  const reader=new FileReader();
  reader.onload=async function(e){
    if(!DB.settings.company) DB.settings.company={};
    const previousUrl = DB.settings.company.signatureUrl;
    DB.settings.company.signatureUrl=e.target.result;
    parametresTable(); // aperçu immédiat pendant la sauvegarde
    const ok = await sync("settings",DB.settings);
    if(ok){
      toast("✅ Signature enregistrée");
    } else {
      // La sauvegarde a échoué : on revient à l'état précédent pour ne pas
      // laisser croire que la signature est enregistrée alors qu'elle ne l'est pas.
      DB.settings.company.signatureUrl = previousUrl;
      parametresTable();
    }
  };
  reader.readAsDataURL(file);
}

async function removeSignature(){
  if(!DB.settings.company) return;
  const previousUrl = DB.settings.company.signatureUrl;
  DB.settings.company.signatureUrl="";
  const ok = await sync("settings",DB.settings);
  if(ok){
    toast("Signature retirée");
  } else {
    DB.settings.company.signatureUrl = previousUrl;
  }
  parametresTable();
}


function editRole(id){
  const r=id?DB.roles.find(x=>x.id===id):{name:"",color:"cyan",perms:Object.fromEntries(MODS.map(m=>[m.k,"none"])),widgets:["kpi_encaisse"]};
  const sysAdmin=!!(r.system&&r.id==="administrateur");
  const colors={cyan:"Cyan",mag:"Magenta",jaune:"Jaune",noir:"Noir"};
  drawer(id?"Rôle · "+r.name:"Nouveau rôle","Droits d'accès",`<form id="f-role">
    <div class="row2"><div class="field"><label>Nom du rôle *</label><input name="name" value="${esc(r.name)}" required></div>
    <div class="field"><label>Couleur</label><select name="color">${Object.keys(colors).map(c=>`<option value="${c}" ${r.color===c?"selected":""}>${colors[c]}</option>`).join("")}</select></div></div>
    <div class="fieldset"><div class="fs-t">Droits par module</div>
      ${sysAdmin?'<p class="muted">L\'administrateur dispose de tous les droits (non modifiable).</p>':''}
      <table class="perms"><thead><tr><th>Module</th><th class="c">Aucun</th><th class="c">Lecture</th><th class="c">Édition</th></tr></thead>
      <tbody>${MODS.map(m=>{const lvl=r.perms[m.k]||"none";return`<tr><td>${m.label}</td>${["none","view","edit"].map(L=>`<td class="c"><input type="radio" name="perm_${m.k}" value="${L}" ${lvl===L?"checked":""} ${sysAdmin?"disabled":""}></td>`).join("")}</tr>`}).join("")}</tbody></table>
    </div>
    <div class="fieldset"><div class="fs-t">Indicateurs du tableau de bord</div>
      <div class="wgrid">${WIDGETS.map(w=>`<label class="wopt"><input type="checkbox" name="w_${w.k}" ${(r.widgets||[]).includes(w.k)?"checked":""}> ${w.label}</label>`).join("")}</div>
    </div>
  </form>`,
  [(id&&!r.system)?{label:"Supprimer",cls:"btn-danger",fn:`delRole('${id}')`}:null,{label:id?"💾 Enregistrer":"Créer",cls:"btn-primary",fn:`saveRole('${id||""}')`}].filter(Boolean));
}
function saveRole(id){
  const f=$("#f-role");const fd=new FormData(f);const name=fd.get("name")?.trim()||"";if(!name){toast("Nom obligatoire");return}
  const existing=id?DB.roles.find(x=>x.id===id):null;
  const sysAdmin=!!(existing&&existing.system&&existing.id==="administrateur");
  const perms={};MODS.forEach(m=>{const sel=f.querySelector('input[name="perm_'+m.k+'"]:checked');perms[m.k]=sel?sel.value:"none"});
  if(sysAdmin)MODS.forEach(m=>perms[m.k]="edit");
  const widgets=WIDGETS.filter(w=>{const el=f.querySelector('input[name="w_'+w.k+'"]');return el&&el.checked}).map(w=>w.k);
  const color=fd.get("color")||"noir";
  if(id){Object.assign(existing,{name,color,perms,widgets});sync("roles",existing)}
  else{const rid=name.toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-+|-+$/g,"")||"role";const r={id:rid+"-"+Math.random().toString(36).slice(2,5),name,color,perms,widgets,system:false};DB.roles.push(r);sync("roles",r)}
  closeOverlays();toast(id?"Rôle mis à jour":"Rôle créé");
  if(USER&&id===(USER.roleId||USER.role_id)){applyNav();refreshUserChip()}
  go("users");
}
function delRole(id){
  const r=DB.roles.find(x=>x.id===id);if(r.system){toast("Rôle système non supprimable");return}
  const n=DB.users.filter(u=>(u.roleId||u.role_id)===id).length;if(n){toast("Réaffectez d'abord les "+n+" compte(s)");return}
  confirmModal("Supprimer ce rôle ?","",()=>{DB.roles=DB.roles.filter(x=>x.id!==id);syncDel("roles",id);closeOverlays();toast("Rôle supprimé");go("users")});
}

