function drawer(title,sub,body,actions){
  const d=$("#drawer");
  const btns=actions&&actions.length?actions.map(a=>`<button class="btn ${a.cls||""} ${a.edit?"act-edit":""}" onclick="${a.fn}">${esc(a.label)}</button>`).join(""):"";
  d.innerHTML=`<div class="drawer-h">
    <div style="flex:1">
      <h3 style="font-size:16px;font-weight:700;margin:0">${esc(title)}</h3>
      ${sub?`<div class="sub" style="font-size:12px;color:var(--txt-2);margin-top:3px">${esc(sub)}</div>`:""}
    </div>
    <button class="btn btn-ghost no-print" onclick="closeOverlays()" style="padding:6px;flex-shrink:0">
      <svg width="18" height="18" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2"><path d="M6 6l12 12M18 6L6 18"/></svg>
    </button>
  </div>
  <div class="drawer-body">${body}</div>
  ${btns?`<div class="drawer-f">${btns}</div>`:""}`;
  $("#scrim").classList.add("show");d.classList.add("show");
}
function modal(body,actions,opts){const m=$("#modal");m.classList.toggle("wide",!!(opts&&opts.wide));m.innerHTML=`<div class="modal-b">${body}<div class="modal-f">${(actions||[]).map(a=>`<button class="btn ${a.cls||""}" onclick="${a.fn}">${esc(a.label)}</button>`).join("")}</div></div>`;$("#scrim").classList.add("show");m.classList.add("show")}
function confirmModal(title,text,onYes){window._confirmCb=onYes;modal(`<h3>${esc(title)}</h3>${text?`<p>${esc(text)}</p>`:"<p></p>"}`,[{label:"Annuler",fn:"closeModal()"},{label:"Confirmer",cls:"btn-danger",fn:"runConfirm()"}])}
function runConfirm(){const cb=window._confirmCb;closeModal();cb&&cb()}
function closeModal(){$("#modal").classList.remove("show","wide");if(!$("#drawer").classList.contains("show"))$("#scrim").classList.remove("show")}
function closeOverlays(){$("#drawer").classList.remove("show");$("#modal").classList.remove("show","wide");$("#scrim").classList.remove("show")}
function kv(k,v){return`<div style="display:flex;justify-content:space-between;gap:16px;padding:5px 0;border-bottom:1px solid var(--ligne-2)"><span class="muted">${k}</span><span class="strong" style="text-align:right">${v==null||v===""?"—":v}</span></div>`}
function emptyState(title,text,btn,fn){return`<div class="empty"><svg class="em-ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4"><rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h5"/></svg><h4>${esc(title)}</h4><div>${esc(text)}</div>${btn?`<button class="btn btn-primary" onclick="${fn}">${esc(btn)}</button>`:""}</div>`}

