async function boot(){
  window.__appStarted = true;
  // Annuler immédiatement le timer HTML — app.js est chargé
  if(typeof window._clearBootTimer === "function") window._clearBootTimer();

  // Vérifier la config
  if(typeof SUPABASE_URL === "undefined" || !SUPABASE_URL || SUPABASE_URL.includes("VOTRE")){
    renderAuth(); return;
  }

  // Valeurs par défaut (l'app fonctionne même sans connexion DB)
  if(!DB.roles)  DB.roles  = defaultRoles();
  if(!DB.users)  DB.users  = [];
  if(!DB.devis)  DB.devis  = [];
  if(!DB.factures)  DB.factures  = [];
  if(!DB.commandes) DB.commandes = [];
  if(!DB.depenses)  DB.depenses  = [];
  if(!DB.employes)  DB.employes  = [];
  if(!DB.conges)    DB.conges    = [];
  if(!DB.stockMvt)  DB.stockMvt  = [];
  if(!DB.caisseMvt) DB.caisseMvt = [];
  if(!DB.planCompta)DB.planCompta= [];
  if(!DB.journal)   DB.journal   = [];
  if(!DB.prodEtapes)   DB.prodEtapes   = [];
  if(!DB.prodActivite) DB.prodActivite = [];
  if(!DB.emailLogs)    DB.emailLogs    = [];
  if(!DB.bonsAchat)    DB.bonsAchat    = [];
  if(!DB.bonsLivraison)DB.bonsLivraison= [];
  if(!DB.activiteInfo) DB.activiteInfo = [];
  if(!DB.settings)     DB.settings     = defaultSettings();
  if(!DB.clients)      DB.clients      = [];
  if(!DB.products)     DB.products     = [];
  if(!DB.fournisseurs) DB.fournisseurs = [];
  if(!DB.caisses)      DB.caisses      = [];
  if(!DB.notifications)DB.notifications= [];

  // Afficher le formulaire de connexion IMMÉDIATEMENT
  renderAuth();

  // Charger les données en arrière-plan (non bloquant).
  // Le chargement est exposé sur window.__loadAllPromise pour que doLogin()
  // puisse patienter dessus si l'utilisateur clique "Se connecter" avant la
  // fin du chargement, au lieu d'afficher à tort "Connexion Supabase impossible".
  window.__loadAllPromise = loadAll().then(() => {
    // Restaurer la session si l'utilisateur était déjà connecté
    try {
      const sid = localStorage.getItem(SESSION_KEY);
      if(sid && DB.users && DB.users.length){
        const u = DB.users.find(x => x.id === sid && x.active !== false);
        if(u && (u.roleId || u.role_id)){
          // enterApp gère tout : nav, session, première route
          enterApp({...u, roleId: u.roleId || u.role_id});
        }
      }
    } catch(e){ console.warn("Session restore:", e); }
  }).catch(e => console.warn("loadAll background:", e));
}
