// ============================================================
// MODULE TIERS — Comptes auxiliaires SYSCOHADA
// Clients (411XXXXX) + Fournisseurs (401XXXXX)
// ============================================================

/* ── Helpers solde & aging ─────────────────────────────────── */

function tiersSolde(compteNum){
  const entries=(DB.journal||[]).filter(e=>e.compte_num===compteNum);
  const debit=entries.reduce((s,e)=>s+(+e.debit||0),0);
  const credit=entries.reduce((s,e)=>s+(+e.credit||0),0);
  return{debit:Math.round(debit),credit:Math.round(credit),solde:Math.round(debit-credit)};
}

function clientAging(clientId){
  const today=new Date();
  const out={current:0,j30:0,j60:0,j90:0,sup90:0};
  (DB.factures||[]).filter(f=>f.clientId===clientId&&factStatut(f)!=="payée"&&factStatut(f)!=="annulé").forEach(f=>{
    const due=f.echeance?new Date(f.echeance):new Date(f.date);
    const days=Math.floor((today-due)/(86400000));
    const reste=Math.max(0,(f.montantTTC||0)-factPaid(f));
    if(days<=0) out.current+=reste;
    else if(days<=30) out.j30+=reste;
    else if(days<=60) out.j60+=reste;
    else if(days<=90) out.j90+=reste;
    else out.sup90+=reste;
  });
  return out;
}

/* ── viewTiers — liste principale ─────────────────────────── */

function viewTiers(){
  if(!vis("compta"))return;
  window._tiersOnglet=window._tiersOnglet||"clients";
  window._tiersQ=window._tiersQ||"";
  const onglet=window._tiersOnglet;

  // KPIs globaux
  const allCli=(DB.clients||[]);
  const allFo=(DB.fournisseurs||[]);
  let totalDebiteurs=0,totalCreanciers=0;
  allCli.forEach(c=>{const cpt=c.compteComptable||c.compte_comptable;if(cpt){const s=tiersSolde(cpt);if(s.solde>0)totalDebiteurs+=s.solde;}});
  allFo.forEach(f=>{const cpt=f.compteComptable||f.compte_comptable;if(cpt){const s=tiersSolde(cpt);if(s.solde<0)totalCreanciers+=Math.abs(s.solde);}});

  const kpi=`<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:12px;margin-bottom:16px">
    <div class="card kpi c-cyan" style="padding:14px 16px"><div class="lab">Clients</div><div class="val tabnum" style="font-size:22px">${allCli.length}</div><div class="delta">${allCli.filter(c=>c.compteComptable||c.compte_comptable).length} avec compte 411</div></div>
    <div class="card kpi c-mag" style="padding:14px 16px"><div class="lab">À encaisser (débiteurs)</div><div class="val tabnum" style="font-size:20px">${fcfa(totalDebiteurs)}</div><div class="delta">Solde journal clients</div></div>
    <div class="card kpi c-jaune" style="padding:14px 16px"><div class="lab">Fournisseurs</div><div class="val tabnum" style="font-size:22px">${allFo.length}</div><div class="delta">${allFo.filter(f=>f.compteComptable||f.compte_comptable).length} avec compte 401</div></div>
    <div class="card kpi c-noir" style="padding:14px 16px"><div class="lab">À payer (créanciers)</div><div class="val tabnum" style="font-size:20px">${fcfa(totalCreanciers)}</div><div class="delta">Solde journal fourn.</div></div>
  </div>`;

  // Onglets
  const TABS=[
    {k:"clients",   label:"👥 Clients (411)",       count:allCli.length},
    {k:"fourn",     label:"🏭 Fournisseurs (401)",   count:allFo.length},
    {k:"comptes",   label:"📊 Comptes auxiliaires",  count:""},
  ];
  const tabs=`<div style="display:flex;gap:0;border-bottom:2px solid var(--ligne);margin-bottom:14px">
    ${TABS.map(t=>{
      const active=onglet===t.k;
      return`<button onclick="window._tiersOnglet='${t.k}';viewTiers()" style="padding:8px 18px;border:none;border-bottom:${active?"2px solid var(--cyan)":"none"};margin-bottom:-2px;cursor:pointer;font-size:12px;font-weight:600;background:transparent;color:${active?"var(--cyan)":"var(--txt-2)"}">${t.label}${t.count!==""?` (${t.count})`:""}</button>`;
    }).join("")}
  </div>`;

  // Actions
  $("#pg-title").textContent="Tiers";
  $("#pg-sub").textContent="Clients · Fournisseurs · Comptes auxiliaires SYSCOHADA 411 / 401";
  $("#pg-actions").innerHTML=`
    <input id="tiers-srch" placeholder="🔍 Nom, compte, NCC…" value="${window._tiersQ}"
      oninput="window._tiersQ=this.value;renderTiersList()"
      class="srch-inp" style="width:200px">
    ${onglet!=="comptes"?`<button class="btn" onclick="exportTiersExcel()" >📊 Excel</button>`:""}
    ${onglet==="clients"&&wr("clients")?`<button class="btn btn-primary act-edit" onclick="editClient()">＋ Client</button>`:""}
    ${onglet==="fourn"&&wr("fournisseurs")?`<button class="btn btn-primary act-edit" onclick="editFournisseur()">＋ Fournisseur</button>`:""}
  `;

  $("#view").innerHTML=kpi+tabs+`<div id="tiers-list"></div>`;
  renderTiersList();
}

function renderTiersList(){
  const onglet=window._tiersOnglet||"clients";
  const q=(window._tiersQ||"").toLowerCase();
  const el=document.getElementById("tiers-list");if(!el)return;

  if(onglet==="comptes"){
    // Onglet Comptes auxiliaires — vue comptable
    const allCli=(DB.clients||[]).filter(c=>c.compteComptable||c.compte_comptable);
    const allFo=(DB.fournisseurs||[]).filter(f=>f.compteComptable||f.compte_comptable);
    const filtered=[
      ...allCli.map(c=>({type:"client",nom:c.nom,compte:c.compteComptable||c.compte_comptable,id:c.id,obj:c})),
      ...allFo.map(f=>({type:"fourn",nom:f.nom,compte:f.compteComptable||f.compte_comptable,id:f.id,obj:f}))
    ].filter(x=>!q||(x.nom||"").toLowerCase().includes(q)||(x.compte||"").includes(q))
     .sort((a,b)=>(a.compte||"").localeCompare(b.compte||""));

    const rows=filtered.map(x=>{
      const s=tiersSolde(x.compte);
      return`<tr class="clk" onclick="openTiers('${x.id}','${x.type==="client"?"client":"fournisseur"}')">
        <td><code style="font-size:11px;color:${x.type==="client"?"var(--cyan)":"var(--mag)"};font-weight:700">${x.compte}</code></td>
        <td><div class="nm">${esc(x.nom)}</div></td>
        <td class="meta">${x.type==="client"?"Client 411":"Fournisseur 401"}</td>
        <td class="r tabnum" style="color:var(--ok)">${s.debit>0?fcfa(s.debit):"—"}</td>
        <td class="r tabnum" style="color:var(--mag)">${s.credit>0?fcfa(s.credit):"—"}</td>
        <td class="r tabnum" style="font-weight:700;color:${s.solde>0?"var(--ok)":s.solde<0?"var(--danger)":"var(--txt-3)"}">${s.solde!==0?fcfa(Math.abs(s.solde))+(s.solde>0?" D":" C"):"—"}</td>
      </tr>`;
    }).join("");
    el.innerHTML=`<div style="overflow-x:auto"><table><thead><tr>
      <th>Compte</th><th>Tiers</th><th>Type</th>
      <th class="r">Débit total</th><th class="r">Crédit total</th><th class="r">Solde</th>
    </tr></thead><tbody>${rows||`<tr><td colspan="6" style="text-align:center;padding:30px;color:var(--txt-3)">Aucun tiers avec compte comptable</td></tr>`}</tbody></table></div>`;
    return;
  }

  if(onglet==="clients"){
    let list=(DB.clients||[]).filter(c=>!q||(c.nom||"").toLowerCase().includes(q)||(c.compteComptable||c.compte_comptable||"").includes(q)||(c.ncc||"").includes(q));
    list=[...list].sort((a,b)=>(a.compteComptable||a.compte_comptable||"zzz").localeCompare(b.compteComptable||b.compte_comptable||"zzz"));
    const today=new Date().toISOString().slice(0,10);
    const rows=list.map(c=>{
      const cpt=c.compteComptable||c.compte_comptable||"";
      const s=cpt?tiersSolde(cpt):{debit:0,credit:0,solde:0};
      const aging=clientAging(c.id);
      const enRetard=aging.j30+aging.j60+aging.j90+aging.sup90;
      const facImpayees=(DB.factures||[]).filter(f=>f.clientId===c.id&&factStatut(f)!=="payée"&&factStatut(f)!=="annulé").length;
      return`<tr class="clk" onclick="openTiers('${c.id}','client')">
        <td><code style="font-size:10px;color:var(--cyan);font-weight:700">${cpt||"—"}</code></td>
        <td><div class="nm">${esc(c.nom)}</div><div class="meta">${esc(c.ncc?"NCC "+c.ncc:"")}</div></td>
        <td class="meta">${esc(c.segment||"")}</td>
        <td class="r tabnum" style="font-weight:700;color:${s.solde>0?"var(--ok)":s.solde<0?"var(--danger)":"var(--txt-3)"}">${s.solde!==0?fcfa(Math.abs(s.solde))+(s.solde>0?" D":" C"):"—"}</td>
        <td class="r">${facImpayees>0?`<span class="pill p-red" style="font-size:10px">${facImpayees}</span>`:""}</td>
        <td class="r" style="color:${enRetard>0?"var(--danger)":"var(--txt-3)"};font-size:11px">${enRetard>0?fcfa(enRetard):"—"}</td>
        <td class="r" onclick="event.stopPropagation()">
          <button class="btn btn-sm btn-ghost" onclick="go('clients')" title="Voir clients">↗</button>
          ${wr("commandes")?`<button class="btn btn-sm" onclick="openSaisieCompta({lignes:[{compte:'${cpt}',libelle:'',debit:0,credit:0},{compte:'',libelle:'',debit:0,credit:0}]})" style="font-size:10px">OD</button>`:""}
        </td>
      </tr>`;
    }).join("");
    el.innerHTML=`<div style="overflow-x:auto"><table><thead><tr>
      <th>Compte 411</th><th>Client</th><th>Segment</th>
      <th class="r">Solde</th><th class="r">Fact. impayées</th><th class="r">En retard</th><th></th>
    </tr></thead><tbody>${rows||`<tr><td colspan="7" style="text-align:center;padding:30px;color:var(--txt-3)">Aucun client</td></tr>`}</tbody></table></div>`;
    return;
  }

  // Onglet Fournisseurs
  if(onglet==="fourn"){
    let list=(DB.fournisseurs||[]).filter(f=>!q||(f.nom||"").toLowerCase().includes(q)||(f.compteComptable||f.compte_comptable||"").includes(q));
    list=[...list].sort((a,b)=>(a.compteComptable||a.compte_comptable||"zzz").localeCompare(b.compteComptable||b.compte_comptable||"zzz"));
    if(!list.length){
      el.innerHTML=`<div style="padding:40px;text-align:center;color:var(--txt-3)">Aucun fournisseur<br><br><button class="btn btn-primary" onclick="editFournisseur()">＋ Ajouter un fournisseur</button></div>`;
      return;
    }
    const rows=list.map(f=>{
      const cpt=f.compteComptable||f.compte_comptable||"";
      const s=cpt?tiersSolde(cpt):{debit:0,credit:0,solde:0};
      const deps=(DB.depenses||[]).filter(d=>(d.fournisseurId||d.fournisseur_id)===f.id);
      const totalAchats=deps.reduce((t,d)=>t+(+d.ttc||0),0);
      const bons=(DB.bonsAchat||[]).filter(b=>(b.fournisseurId||b.fournisseur_id)===f.id);
      return`<tr class="clk" onclick="openTiers('${f.id}','fournisseur')">
        <td><code style="font-size:10px;color:var(--mag);font-weight:700">${cpt||"—"}</code></td>
        <td><div class="nm">${esc(f.nom)}</div><div class="meta">${esc(f.secteur||"")}</div></td>
        <td class="meta">${esc(f.tel||"")}${f.email?`<br><span style="font-size:10px">${esc(f.email)}</span>`:""}</td>
        <td class="r tabnum" style="font-weight:700;color:${s.solde<0?"var(--danger)":s.solde>0?"var(--ok)":"var(--txt-3)"}">${s.solde!==0?fcfa(Math.abs(s.solde))+(s.solde>0?" D":" C"):"—"}</td>
        <td class="r tabnum meta">${totalAchats>0?fcfa(totalAchats):"—"}</td>
        <td class="r">${bons.filter(b=>b.statut!=="reçu"&&b.statut!=="annulé").length>0?`<span class="pill p-cyan" style="font-size:10px">${bons.filter(b=>b.statut!=="reçu"&&b.statut!=="annulé").length} BA</span>`:""}</td>
        <td class="r" onclick="event.stopPropagation()">
          <button class="btn btn-sm btn-ghost" onclick="go('fournisseurs')" title="Voir fournisseurs">↗</button>
          ${wr("fournisseurs")?`<button class="btn btn-sm" onclick="editBonAchat('',{fournisseurId:'${f.id}'})" style="font-size:10px">BA</button>`:""}
        </td>
      </tr>`;
    }).join("");
    el.innerHTML=`<div style="overflow-x:auto"><table><thead><tr>
      <th>Compte 401</th><th>Fournisseur</th><th>Contact</th>
      <th class="r">Solde</th><th class="r">Achats</th><th class="r">Bons achat</th><th></th>
    </tr></thead><tbody>${rows}</tbody></table></div>`;
  }
}

function openTiers(id, type){
  const isClient=type==="client";
  const entity=isClient
    ?(DB.clients||[]).find(x=>x.id===id)
    :(DB.fournisseurs||[]).find(x=>x.id===id);
  if(!entity) return;

  const cpt=entity.compteComptable||entity.compte_comptable||"";
  const s=cpt?tiersSolde(cpt):{debit:0,credit:0,solde:0};

  // Écritures liées à ce compte
  const ecritures=(DB.journal||[]).filter(e=>e.compte_num===cpt).sort((a,b)=>new Date(b.date||0)-new Date(a.date||0));

  // Factures (clients uniquement)
  const factures=isClient?(DB.factures||[]).filter(f=>f.clientId===id).sort((a,b)=>new Date(b.date||0)-new Date(a.date||0)):[];
  const facImpayees=factures.filter(f=>factStatut(f)!=="payée"&&factStatut(f)!=="annulé");

  // Balance âgée (clients)
  const aging=isClient?clientAging(id):null;

  let body=`<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:14px;font-size:12.5px">
    ${kv("Compte tiers","<code style='font-size:14px;font-weight:700;color:"+(isClient?"var(--cyan)":"var(--mag)")+"'>"+(cpt||"Non assigné")+"</code>")}
    ${kv("Type",isClient?"Client (411)":"Fournisseur (401)")}
    ${entity.ncc?kv("NCC",esc(entity.ncc)):""}
    ${entity.tel?kv("Téléphone",esc(entity.tel)):""}
  </div>`;

  // KPIs solde
  body+=`<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;margin-bottom:14px">
    <div style="padding:10px 12px;border-radius:8px;background:rgba(0,174,239,.08);border:1px solid rgba(0,174,239,.2)">
      <div style="font-size:10px;color:var(--txt-2);text-transform:uppercase;letter-spacing:.08em;margin-bottom:4px">Total Débit</div>
      <div style="font-family:monospace;font-weight:700;font-size:15px">${fcfa(s.debit)}</div>
    </div>
    <div style="padding:10px 12px;border-radius:8px;background:rgba(225,0,152,.08);border:1px solid rgba(225,0,152,.2)">
      <div style="font-size:10px;color:var(--txt-2);text-transform:uppercase;letter-spacing:.08em;margin-bottom:4px">Total Crédit</div>
      <div style="font-family:monospace;font-weight:700;font-size:15px">${fcfa(s.credit)}</div>
    </div>
    <div style="padding:10px 12px;border-radius:8px;background:${s.solde>0?"rgba(0,200,83,.1)":s.solde<0?"rgba(244,67,54,.1)":"var(--papier)"};border:1.5px solid ${s.solde>0?"var(--ok)":s.solde<0?"var(--danger)":"var(--ligne)"}">
      <div style="font-size:10px;color:var(--txt-2);text-transform:uppercase;letter-spacing:.08em;margin-bottom:4px">Solde</div>
      <div style="font-family:monospace;font-weight:700;font-size:15px;color:${s.solde>0?"var(--ok)":s.solde<0?"var(--danger)":"var(--txt-2)"}">${fcfa(Math.abs(s.solde))} ${s.solde>0?"D":s.solde<0?"C":"—"}</div>
    </div>
  </div>`;

  // Balance âgée (clients seulement)
  if(isClient && aging){
    const totalEnRetard=aging.j30+aging.j60+aging.j90+aging.sup90;
    body+=`<div class="fieldset" style="margin-bottom:12px">
      <div class="fs-t">Balance âgée — Créances impayées</div>
      <div style="display:grid;grid-template-columns:repeat(5,1fr);gap:6px;margin-top:8px;font-size:11px">
        <div style="text-align:center;padding:8px 4px;border-radius:6px;background:rgba(0,200,83,.1)">
          <div style="color:var(--txt-2);margin-bottom:4px">Non échu</div>
          <div style="font-weight:700;color:var(--ok)">${fcfa(aging.current)||"—"}</div>
        </div>
        <div style="text-align:center;padding:8px 4px;border-radius:6px;background:rgba(255,196,0,.12)">
          <div style="color:var(--txt-2);margin-bottom:4px">0 – 30j</div>
          <div style="font-weight:700;color:#856404">${aging.j30>0?fcfa(aging.j30):"—"}</div>
        </div>
        <div style="text-align:center;padding:8px 4px;border-radius:6px;background:rgba(255,152,0,.12)">
          <div style="color:var(--txt-2);margin-bottom:4px">31 – 60j</div>
          <div style="font-weight:700;color:#e65100">${aging.j60>0?fcfa(aging.j60):"—"}</div>
        </div>
        <div style="text-align:center;padding:8px 4px;border-radius:6px;background:rgba(244,67,54,.1)">
          <div style="color:var(--txt-2);margin-bottom:4px">61 – 90j</div>
          <div style="font-weight:700;color:var(--danger)">${aging.j90>0?fcfa(aging.j90):"—"}</div>
        </div>
        <div style="text-align:center;padding:8px 4px;border-radius:6px;background:rgba(183,28,28,.1)">
          <div style="color:var(--txt-2);margin-bottom:4px">+90j</div>
          <div style="font-weight:700;color:#b71c1c">${aging.sup90>0?fcfa(aging.sup90):"—"}</div>
        </div>
      </div>
      ${totalEnRetard>0?`<div style="margin-top:8px;padding:6px 10px;background:rgba(244,67,54,.08);border-radius:6px;font-size:11px;color:var(--danger);font-weight:600">⚠️ Total en retard : ${fcfa(totalEnRetard)}</div>`:"<div style='margin-top:6px;font-size:11px;color:var(--ok)'>✅ Aucune créance en retard</div>"}
    </div>`;
  }

  // Factures liées (clients)
  if(factures.length){
    body+=`<div class="fieldset" style="margin-bottom:12px">
      <div class="fs-t">Factures (${factures.length}) — ${facImpayees.length} impayée(s)</div>
      <div style="max-height:200px;overflow-y:auto;margin-top:8px">
        ${factures.slice(0,10).map(f=>{
          const st=factStatut(f);const reste=Math.max(0,f.montantTTC-factPaid(f));
          return`<div style="display:flex;justify-content:space-between;align-items:center;padding:5px 0;border-bottom:1px solid var(--ligne-2)">
            <div>
              <span style="font-family:monospace;font-weight:600;font-size:11px;cursor:pointer;color:var(--cyan)" onclick="closeOverlays();openFacture('${f.id}')">${esc(f.numero||"")}</span>
              <span class="meta" style="margin-left:8px">${fdate(f.date)}</span>
              ${f.echeance?`<span class="meta" style="margin-left:6px;color:${new Date(f.echeance)<new Date()&&st!=="payée"?"var(--danger)":"var(--txt-3)"}">Éch. ${fdate(f.echeance)}</span>`:""}
            </div>
            <div style="display:flex;gap:8px;align-items:center">
              ${pill(st)}
              <span style="font-family:monospace;font-weight:700;font-size:12px">${fcfa(f.montantTTC)}</span>
              ${reste>0?`<span style="font-size:10px;color:var(--danger);font-weight:600">Reste: ${fcfa(reste)}</span>`:""}
            </div>
          </div>`;
        }).join("")}
        ${factures.length>10?`<div style="text-align:center;font-size:11px;color:var(--txt-3);margin-top:6px">+ ${factures.length-10} autres</div>`:""}
      </div>
    </div>`;
  }

  // Historique écritures comptables
  if(ecritures.length){
    body+=`<div class="fieldset" style="margin-bottom:12px">
      <div class="fs-t">Écritures (${ecritures.length}) — Journal ${cpt}</div>
      <div style="max-height:220px;overflow-y:auto;margin-top:8px">
        <table style="width:100%;font-size:11px"><thead>
          <tr style="background:var(--papier)">
            <th style="padding:4px 6px">Date</th>
            <th style="padding:4px 6px">Jnl</th>
            <th style="padding:4px 6px">Pièce</th>
            <th style="padding:4px 6px">Libellé</th>
            <th style="padding:4px 6px;text-align:right">Débit</th>
            <th style="padding:4px 6px;text-align:right">Crédit</th>
            <th style="padding:4px 6px;text-align:right">Solde cumulé</th>
          </tr>
        </thead><tbody>
        ${(()=>{let cum=0;return ecritures.slice().reverse().map(e=>{cum+=((+e.debit||0)-(+e.credit||0));return`<tr style="border-bottom:1px solid var(--ligne-2)">
            <td style="padding:3px 6px;white-space:nowrap">${fdate(e.date)}</td>
            <td style="padding:3px 6px;font-weight:600;color:var(--cyan)">${esc(e.journal_code||"")}</td>
            <td style="padding:3px 6px;font-family:monospace">${esc(e.numero_piece||"")}</td>
            <td style="padding:3px 6px;max-width:180px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(e.libelle||"")}</td>
            <td style="padding:3px 6px;text-align:right;color:var(--ok)">${e.debit>0?fcfa(e.debit):""}</td>
            <td style="padding:3px 6px;text-align:right;color:var(--mag)">${e.credit>0?fcfa(e.credit):""}</td>
            <td style="padding:3px 6px;text-align:right;font-weight:700;color:${cum>0?"var(--ok)":cum<0?"var(--danger)":"var(--txt-2)"}">${fcfa(Math.abs(cum))} ${cum>0?"D":cum<0?"C":""}</td>
          </tr>`;}).reverse().join("")})()}
        </tbody></table>
      </div>
    </div>`;
  } else if(cpt){
    body+=`<div style="padding:14px;text-align:center;color:var(--txt-3);font-size:12px">Aucune écriture pour le compte ${cpt}</div>`;
  }

  const actions=[
    cpt?{label:"✏️ Saisir OD",cls:"btn-primary",fn:`closeOverlays();openSaisieCompta({lignes:[{compte:'${cpt}',libelle:'',debit:${isClient?0:0},credit:${isClient?0:0}},{compte:'',libelle:'',debit:0,credit:0}]})`}:null,
    isClient&&facImpayees.length?{label:"🔔 Relancer",cls:"btn",fn:`closeOverlays();openRelanceEmail && openRelanceEmail('${facImpayees[0]?.id||""}')`}:null,
    isClient?{label:"+ Facture",cls:"btn",fn:`closeOverlays();editDoc('factures')`}:null,
  ].filter(Boolean);

  drawer(
    cpt||(isClient?"Client":"Fournisseur"),
    entity.nom,
    body,
    actions
  );
}

function exportTiersExcel(){
  const onglet=window._tiersOnglet||"clients";
  const isClient=onglet==="clients";
  const list=isClient?(DB.clients||[]):(DB.fournisseurs||[]);
  const rows=list.map(e=>{
    const cpt=e.compteComptable||e.compte_comptable||"";
    const s=cpt?tiersSolde(cpt):{debit:0,credit:0,solde:0};
    return{
      "Compte":cpt,"Nom":e.nom,"NCC/Numéro Contrib.":e.ncc||e.numeroContribuable||"",
      "Téléphone":e.tel||"","Email":e.email||"",
      "Total Débit":s.debit,"Total Crédit":s.credit,
      "Solde (D-C)":s.solde,"Sens":s.solde>0?"D":s.solde<0?"C":"—"
    };
  });
  // Réutiliser la fonction export existante
  const header=Object.keys(rows[0]||{});
  const csv=[header.join(";"),...rows.map(r=>header.map(h=>r[h]??""  ).join(";"))].join("\n");
  const blob=new Blob(["\uFEFF"+csv],{type:"text/csv;charset=utf-8"});
  const a=document.createElement("a");
  a.href=URL.createObjectURL(blob);
  a.download="tiers-"+(isClient?"clients":"fournisseurs")+"-"+todayISO()+".csv";
  a.click();
}


