function viewBonsLivraison(){
  if(!vis("livraison"))return;
  const all=DB.bonsLivraison||[];
  const BL_FLOW=[["brouillon","📝 Brouillon"],["émis","📤 Émis"],["signé","✅ Signé"],["archivé","🗄️ Archivé"]];

  const kpi=`<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:12px;margin-bottom:16px">
    <div class="card kpi c-cyan" style="padding:14px 16px"><div class="lab">Bons émis</div><div class="val tabnum" style="font-size:22px">${all.length}</div><div class="delta">${all.filter(b=>b.statut==="émis").length} en cours</div></div>
    <div class="card kpi c-jaune" style="padding:14px 16px"><div class="lab">À faire signer</div><div class="val tabnum" style="font-size:22px">${all.filter(b=>b.statut==="émis").length}</div><div class="delta">en attente signature</div></div>
    <div class="card kpi c-noir" style="padding:14px 16px"><div class="lab">Signés</div><div class="val tabnum" style="font-size:22px">${all.filter(b=>b.statut==="signé").length}</div><div class="delta">livraisons confirmées</div></div>
  </div>`;

  $("#pg-actions").innerHTML=wr("livraison")?`<button class="btn btn-primary act-edit" onclick="editBonLivraison()">＋ Nouveau bon de livraison</button>`:"";

  if(!all.length){
    $("#view").innerHTML=kpi+emptyState("Aucun bon de livraison","Créez des bons depuis une commande ou ici.","Nouveau bon","editBonLivraison()");
    return;
  }

  const sorted=[...all].sort((a,b)=>new Date(b.createdAt||b.created_at||0)-new Date(a.createdAt||a.created_at||0));
  const rows=sorted.map(b=>{
    const cmd=(DB.commandes||[]).find(x=>x.id===(b.commandeId||b.commande_id));
    return `<tr class="clk" onclick="openBonLivraison('${b.id}')">
      <td><div class="nm tabnum">${esc(b.numero||"")}</div></td>
      <td>${esc(clientName(b.clientId||b.client_id))}</td>
      <td class="meta">${fdate(b.date||b.created_at)}</td>
      <td class="meta">${cmd?`<span style="color:var(--cyan)">${esc(cmd.numero||cmd.titre)}</span>`:"—"}</td>
      <td>${pill(b.statut||"brouillon")}</td>
      <td class="meta">${esc(b.signataire||"")}</td>
      <td class="r" onclick="event.stopPropagation()">
        ${wr("livraison")?`<button class="btn btn-sm btn-ghost" onclick="printBonLivraison('${b.id}')">🖨️</button>
        <button class="btn btn-sm btn-ghost act-edit" onclick="editBonLivraison('${b.id}')">✏️</button>`:""}
      </td>
    </tr>`;
  }).join("");

  $("#view").innerHTML=kpi+`<div style="overflow-x:auto"><table>
    <thead><tr><th>N° BL</th><th>Client</th><th>Date</th><th>Commande</th><th>Statut</th><th>Signataire</th><th></th></tr></thead>
    <tbody>${rows}</tbody>
  </table></div>`;
}

function editBonLivraison(id, prefill){
  if(!guard("livraison"))return;
  const b=id?(DB.bonsLivraison||[]).find(x=>x.id===id)||{}:(prefill||{});
  const lignes=b.lignes||[{reference:"",designation:"",unite:"U",quantiteCommandee:1,quantiteLivree:1}];
  const clientOpts=clientsAlpha().map(c=>`<option value="${c.id}" ${(b.clientId||b.client_id||prefill?.clientId||"")===c.id?"selected":""}>${esc(c.nom)}</option>`).join("");
  const cmdOpts=(DB.commandes||[]).map(c=>`<option value="${c.id}" ${(b.commandeId||b.commande_id||prefill?.commandeId||"")===c.id?"selected":""}>${esc(c.numero||"")} — ${esc(c.titre||"")}</option>`).join("");
  const statOpts=[["brouillon","📝 Brouillon"],["émis","📤 Émis"],["signé","✅ Signé"],["archivé","🗄️ Archivé"]].map(([k,l])=>`<option value="${k}" ${(b.statut||"brouillon")===k?"selected":""}>${l}</option>`).join("");
  const UNITES=["U","M²","ML","Kg","Pcs","Ex.","Résme","Boîte","Lot","Fft"];
  const lignesHtml=lignes.map((l,i)=>{
    const uOpts=UNITES.map(u=>`<option value="${u}" ${(l.unite||"U")===u?"selected":""}>${u}</option>`).join("");
    return `<tr>
      <td><input style="width:70px;font-size:11px;font-family:monospace" value="${esc(l.reference||"")}" placeholder="Réf" onchange="updBLLigne(${i},'reference',this.value)"></td>
      <td><input style="width:100%" value="${esc(l.designation||"")}" placeholder="Désignation" onchange="updBLLigne(${i},'designation',this.value)"></td>
      <td><select style="width:58px;font-size:11px" onchange="updBLLigne(${i},'unite',this.value)">${uOpts}</select></td>
      <td><input type="number" value="${l.quantiteCommandee||1}" min="0" style="width:60px" onchange="updBLLigne(${i},'quantiteCommandee',+this.value)"></td>
      <td><input type="number" value="${l.quantiteLivree!=null?l.quantiteLivree:l.quantiteCommandee||1}" min="0" style="width:60px;font-weight:700" onchange="updBLLigne(${i},'quantiteLivree',+this.value)"></td>
      <td><button type="button" class="btn btn-sm btn-ghost" onclick="delBLLigne(${i})">✕</button></td>
    </tr>`;
  }).join("");
  window._editingBL={id:id||null,lignes:JSON.parse(JSON.stringify(lignes))};
  drawer(id?"Modifier le bon de livraison":"Nouveau bon de livraison","",`<form id="f-bl">
    <div class="row2">
      <div class="field"><label>Client *</label><select name="clientId"><option value="">— Choisir —</option>${clientOpts}</select></div>
      <div class="field"><label>Date</label><input name="date" type="date" value="${b.date||todayISO()}"></div>
    </div>
    <div class="row2">
      <div class="field"><label>Commande associée</label><select name="commandeId"><option value="">— Aucune —</option>${cmdOpts}</select></div>
      <div class="field"><label>Statut</label><select name="statut">${statOpts}</select></div>
    </div>
    <div class="fieldset" style="margin:10px 0">
      <div class="fs-t">Articles livrés</div>
      <div style="overflow-x:auto"><table id="t-bl-lignes">
        <thead><tr><th style="width:72px">Réf.</th><th>Désignation</th><th style="width:60px">Unité</th><th style="width:62px">Qté cmdée</th><th style="width:62px">Qté livrée</th><th style="width:36px"></th></tr></thead>
        <tbody id="bl-lignes-body">${lignesHtml}</tbody>
      </table></div>
      <button type="button" class="btn btn-sm" style="margin-top:8px" onclick="addBLLigne()">+ Article</button>
    </div>
    <div class="row2">
      <div class="field"><label>Signataire (réceptionnaire)</label><input name="signataire" value="${esc(b.signataire||"")}"></div>
      <div class="field"><label>Lieu de livraison</label><input name="lieu" value="${esc(b.lieu||"")}"></div>
    </div>
    <div class="field"><label>Notes / Observations</label><textarea name="notes">${esc(b.notes||"")}</textarea></div>
  </form>`,
    [id?{label:"Supprimer",cls:"btn-danger",fn:`delBonLivraison('${id}')`}:null,
     id?{label:"🖨️ Imprimer",cls:"btn",fn:`printBonLivraison('${id}')`}:null,
     {label:id?"💾 Enregistrer":"Créer le bon",cls:"btn-primary",fn:`saveBonLivraison('${id||""}')`}
    ].filter(Boolean)
  );
}

function updBLLigne(i,k,v){if(!window._editingBL)return;window._editingBL.lignes[i][k]=v;}
function addBLLigne(){
  if(!window._editingBL)return;
  const nl={reference:"",designation:"",unite:"U",quantiteCommandee:1,quantiteLivree:1};
  window._editingBL.lignes.push(nl);
  const i=window._editingBL.lignes.length-1;
  const UNITES=["U","M²","ML","Kg","Pcs","Ex.","Résme","Boîte","Lot","Fft"];
  const uOpts=UNITES.map(u=>`<option value="${u}" ${u==="U"?"selected":""}>${u}</option>`).join("");
  const tbody=document.getElementById("bl-lignes-body");
  if(tbody){const tr=document.createElement("tr");tr.innerHTML=`<td><input style="width:70px;font-size:11px;font-family:monospace" placeholder="Réf" onchange="updBLLigne(${i},'reference',this.value)"></td><td><input style="width:100%" placeholder="Désignation" onchange="updBLLigne(${i},'designation',this.value)"></td><td><select style="width:58px;font-size:11px" onchange="updBLLigne(${i},'unite',this.value)">${uOpts}</select></td><td><input type="number" value="1" min="0" style="width:60px" onchange="updBLLigne(${i},'quantiteCommandee',+this.value)"></td><td><input type="number" value="1" min="0" style="width:60px;font-weight:700" onchange="updBLLigne(${i},'quantiteLivree',+this.value)"></td><td><button type="button" class="btn btn-sm btn-ghost" onclick="delBLLigne(${i})">✕</button></td>`;tbody.appendChild(tr);}
}
function delBLLigne(i){if(!window._editingBL)return;window._editingBL.lignes.splice(i,1);const id=window._editingBL.id;editBonLivraison(id||"",(id?null:{}));}

async function saveBonLivraison(id){
  if(!guard("livraison"))return;
  const f=document.getElementById("f-bl");if(!f)return;
  const fd=new FormData(f);
  if(!fd.get("clientId")){toast("Client obligatoire");return;}
  const lignes=window._editingBL?window._editingBL.lignes:[{designation:"",quantiteLivree:1}];
  const patch={
    clientId:fd.get("clientId"),date:fd.get("date")||todayISO(),
    commandeId:fd.get("commandeId")||null,statut:fd.get("statut")||"brouillon",
    signataire:fd.get("signataire")||"",lieu:fd.get("lieu")||"",
    lignes,notes:fd.get("notes")||""
  };
  if(id){
    const b=(DB.bonsLivraison||[]).find(x=>x.id===id);
    if(b) Object.assign(b,patch);
    await dbUpsert("crm_bons_livraison",{id,...patch});
  } else {
    const seq=(DB.settings.seqBonLivraison||1);const year=DB.settings.year||new Date().getFullYear();
    const num="BL-"+year+"-"+String(seq).padStart(4,"0");
    const b={id:uid(),numero:num,...patch,createdAt:Date.now()};
    DB.bonsLivraison=DB.bonsLivraison||[];DB.bonsLivraison.push(b);
    DB.settings.seqBonLivraison=(seq+1);
    await dbUpsert("crm_bons_livraison",b);sync("settings",DB.settings);
  }
  window._editingBL=null;closeOverlays();toast(id?"Bon mis à jour ✓":"Bon de livraison créé ✓");go("livraison");
}

function openBonLivraison(id){
  if(!vis("livraison"))return;
  const b=(DB.bonsLivraison||[]).find(x=>x.id===id);if(!b)return;
  const cmd=(DB.commandes||[]).find(x=>x.id===(b.commandeId||b.commande_id));
  const facOrigine=(DB.factures||[]).find(x=>x.id===(b.factureId||b.facture_id));
  let body=`<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:12px">
    ${kv("Client","<strong>"+esc(clientName(b.clientId||b.client_id))+"</strong>")}
    ${kv("Statut",pill(b.statut||"brouillon"))}
    ${kv("Date",fdate(b.date||b.created_at))}
    ${cmd?kv("Commande","<span style='color:var(--cyan)'>"+esc(cmd.numero||cmd.titre)+"</span>"):""}
    ${facOrigine?kv("Facture d'origine","<span style='color:var(--cyan)'><strong>"+esc(facOrigine.numero||"")+"</strong></span> <button class=\"btn btn-sm btn-ghost\" style=\"font-size:10px;padding:1px 6px\" onclick=\"closeOverlays();openDoc('factures','"+facOrigine.id+"')\">Voir →</button>"):""}
    ${b.signataire?kv("Signataire",esc(b.signataire)):""}
    ${b.lieu?kv("Lieu",esc(b.lieu)):""}
  </div>
  <div style="overflow-x:auto;margin:8px 0"><table style="font-size:12px">
    <thead><tr><th>Réf.</th><th>Désignation</th><th>Unité</th><th class="r">Cmdée</th><th class="r">Livrée</th><th class="r">Écart</th></tr></thead>
    <tbody>${(b.lignes||[]).map(l=>{
      const ec=(l.quantiteLivree||0)-(l.quantiteCommandee||0);
      return`<tr>
        <td style="font-family:monospace;font-size:11px">${esc(l.reference||"")}</td>
        <td>${esc(l.designation||"")}</td>
        <td style="text-align:center">${esc(l.unite||"U")}</td>
        <td class="r tabnum">${l.quantiteCommandee||0}</td>
        <td class="r tabnum" style="font-weight:700">${l.quantiteLivree||0}</td>
        <td class="r" style="color:${ec<0?"var(--danger)":ec>0?"var(--ok)":"var(--txt-2)"};font-weight:600">${ec>0?"+":""}${ec}</td>
      </tr>`;
    }).join("")}</tbody>
  </table></div>`;
  if(b.notes) body+=kv("Notes","<span style='white-space:pre-wrap'>"+esc(b.notes)+"</span>");
  drawer(b.numero||"Bon de livraison",clientName(b.clientId||b.client_id),body,
    [wr("livraison")?{label:"🖨️ Imprimer",cls:"btn",fn:`printBonLivraison('${id}')`}:null,
     wr("livraison")?{label:"✏️ Modifier",cls:"btn",fn:`closeOverlays();editBonLivraison('${id}')`}:null,
     wr("livraison")?{label:"Supprimer",cls:"btn-danger",fn:`delBonLivraison('${id}')`}:null
    ].filter(Boolean)
  );
}

