  const b=(DB.bonsLivraison||[]).find(x=>x.id===id);if(!b)return;
  const co=DB.settings.company||{};
  const lignesHtml=(b.lignes||[]).map((l,i)=>
    `<tr><td class="num">${i+1}</td><td style="font-family:monospace;font-size:11px">${esc(l.reference||"")}</td>`+
    `<td>${esc(l.designation||"")}</td><td style="text-align:center">${esc(l.unite||"U")}</td>`+
    `<td class="right">${l.quantiteCommandee||0}</td><td class="right qty-livree">${l.quantiteLivree||0}</td></tr>`
  ).join("");
  const css=`*{margin:0;padding:0;box-sizing:border-box}*{-webkit-print-color-adjust:exact!important;print-color-adjust:exact!important;color-adjust:exact!important}html,body{width:100%;height:100%;background:#fff;font-family:-apple-system,'Segoe UI',sans-serif}body{font-size:13px;color:#1a1a1c;line-height:1.5;padding:20px;max-width:A4}.container{max-width:820px;margin:0 auto}.header{display:grid;grid-template-columns:auto 1fr auto;gap:20px;align-items:center;margin-bottom:24px;padding-bottom:16px;border-bottom:3px solid #0066cc}.header .logo-sec{text-align:center}.header .logo-sec img{height:70px;opacity:0.9}.header .company-sec h1{font-size:22px;font-weight:700;color:#0066cc;margin:0}.header .company-sec p{font-size:11px;color:#666;margin:3px 0}.header .doc-sec{text-align:right}.doc-number{font-size:36px;font-weight:900;color:#0066cc;letter-spacing:1px;font-family:monospace}.doc-date{font-size:12px;color:#333;margin-top:8px}.section-title{font-size:10px;font-weight:700;text-transform:uppercase;color:#999;margin-top:20px;margin-bottom:8px}.client-box{background:linear-gradient(135deg,#f0f7ff 0%,#f9fcff 100%);border-left:4px solid #0066cc;padding:12px 14px;border-radius:4px;margin-bottom:18px}.client-box .name{font-size:14px;font-weight:600;color:#1a1a1c}table{width:100%;border-collapse:collapse;margin-bottom:20px}thead{background:#003d99;color:#fff}thead th{padding:11px 10px;text-align:left;font-size:12px;font-weight:600;letter-spacing:0.3px}tbody td{padding:10px;border-bottom:1px solid #e0e0e0;font-size:12px}tbody tr:nth-child(odd){background:#f9f9f9}tbody tr:nth-child(even){background:#fff}tbody td.num{text-align:center;color:#999;width:30px;font-size:11px}tbody td.right{text-align:right;font-family:monospace;font-weight:500}tbody td.qty-livree{color:#0066cc;font-weight:600}.notes-box{background:#fff8e1;border-left:4px solid #ffc107;padding:12px 14px;border-radius:4px;margin-bottom:20px}.notes-box .title{font-size:11px;font-weight:700;color:#f57c00;margin-bottom:6px}.notes-box .text{font-size:12px;color:#333;white-space:pre-wrap}.signature-block{display:grid;grid-template-columns:1fr auto 1fr;gap:16px;margin-top:32px;padding-top:20px;border-top:1px solid #d0d0d0}.sign-zone{text-align:center}.sign-zone .label{font-size:10px;font-weight:700;text-transform:uppercase;color:#666;margin-bottom:50px}.sign-line{border-top:1px solid #000;height:35px}.sign-caption{font-size:9px;color:#999;margin-top:6px}.logo-center{text-align:center}.logo-center img{height:65px;opacity:0.85}.sign-info h3{font-size:13px;font-weight:700;color:#1a1a1c;margin:0 0 4px 0}.sign-info p{font-size:11px;color:#666;margin:0}.footer{font-size:9px;color:#999;text-align:center;margin-top:24px;padding-top:12px;border-top:1px solid #e0e0e0}@media print{body{padding:0;margin:0}.container{max-width:100%}}`
  const html="<!DOCTYPE html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>BL "+esc(b.numero||"")+"</title><style>"+css+"</style></head><body><div class='container'><div class='header'><div class='logo-sec'><img src='"+LOGO_CREATIS_B64+"' alt='Creatis Studio' style='height:70px;width:auto;opacity:0.95'></div><div class='company-sec'><div>"+esc(co.siege||"Cocody Val Doyen 4, Abidjan")+"</div><div>"+esc(co.tel||"")+" · "+esc(co.email||"")+"</div><div>RC : "+esc(co.rc||"")+" · CC : "+esc(co.cc||"")+"</div></div><div class='doc-meta'><div class='doc-type'>BL</div><div class='doc-num'>"+esc(b.numero||"")+"</div><div class='doc-date'>"+fdate(b.date||b.created_at)+"</div>"+(b.lieu?"<div class='doc-date' style='margin-top:10px'>📍 "+esc(b.lieu)+"</div>":"")+"</div></div><div class='section'><div class='section-title'>Destinataire</div><div class='client-box'><div class='name'>"+esc(clientName(b.clientId||b.client_id))+"</div></div></div><table><thead><tr><th style='width:40px'>#</th><th style='width:90px'>Réf.</th><th>Désignation</th><th style='width:70px;text-align:center'>Unité</th><th style='width:90px;text-align:right'>Commandée</th><th style='width:90px;text-align:right'>Livrée</th></tr></thead><tbody>"+lignesHtml+"</tbody></table>"+(b.notes?"<div class='notes-box'><div class='notes-title'>Observations</div><div class='notes-text'>"+esc(b.notes)+"</div></div>":"")+"<div class='signature-block'><div class='sign-zone'><div class='sign-label'>Réceptionnaire</div><div class='sign-line'></div><div class='sign-caption'>Signature & date</div></div><div class='creatis-logo'><img src='"+SIG_CREATIS_B64+"' alt='Logo Creatis Studio' style='height:60px;width:auto'></div><div class='sign-zone'><div class='sign-info'><div class='title'>Creatis Studio</div><div class='role'>Responsable livraison</div></div></div></div><div class='footer'>"+esc(co.name||"Creatis Studio")+" · "+esc(co.siege||"")+" · "+esc(co.tel||"")+" · "+esc(co.site||"www.creatis-ci.com")+"</div></div></body></html>";
  const w=window.open("","_blank","width=900,height=700");if(w){w.document.write(html);w.document.close();setTimeout(()=>w.print(),400);}
