async function saveMvtCaisse(){
  const gv=id=>document.getElementById(id)?.value?.trim()||"";
  const caisseId=gv("cmvt-caisse");
  if(!caisseId){toast("Sélectionnez une caisse");return;}
  const montant=+document.getElementById("cmvt-mt").value||0;
  if(!montant){toast("Montant invalide");return;}
  const libelle=gv("cmvt-lib");
  if(!libelle){toast("Libellé requis");return;}
  const typeMvt=gv("cmvt-type");

  const c=(DB.caisses||[]).find(x=>x.id===caisseId);
  let solde=+c?.solde_initial||0;
  (DB.caisseMvt||[]).filter(m=>m.caisse_id===caisseId)
    .forEach(m=>{solde+=(m.type_mvt==="entree"?+m.montant:-+m.montant);});
  const soldeApres=typeMvt==="entree"?solde+montant:solde-montant;

  const mvt={
    id:crypto.randomUUID(),date:gv("cmvt-date"),caisse_id:caisseId,
    type_mvt:typeMvt,montant,libelle,categorie:gv("cmvt-cat"),
    reference:gv("cmvt-ref"),solde_avant:solde,solde_apres:soldeApres,
  };
  const ok=await dbUpsert("crm_caisse_mvt",mvt);
  if(!ok)return;
  (DB.caisseMvt=DB.caisseMvt||[]).push(mvt);
  const devise=DB.settings.devise||"F CFA";
  // ── Écriture comptable automatique ──────────────────────────
  // Trouver le compte comptable de la caisse (57XXXXX ou 52XXXXX)
  const caisseCompta=c?.compte_comptable_num||c?.compteNum||(typeMvt==="entree"?"57100000":"57100000");
  const contrepartie=gv("cmvt-cat-compte")||""; // optionnel
  if(DB.settings.autoEcritureCaisse!==false){
    const piece="CA-"+mvt.id.slice(-6).toUpperCase();
    const jour=mvt.date||todayISO();
    const ecritures=[];
    if(typeMvt==="entree"){
      // Débit Caisse (57) / Crédit compte de produit ou client
      ecritures.push({id:crypto.randomUUID(),date:jour,journal_code:"CA",libelle,reference:mvt.reference||libelle,numero_piece:piece,compte_num:caisseCompta,compte_lib:"Caisse",debit:montant,credit:0,tva:0});
      if(contrepartie) ecritures.push({id:crypto.randomUUID(),date:jour,journal_code:"CA",libelle,reference:mvt.reference||libelle,numero_piece:piece,compte_num:contrepartie,compte_lib:(DB.planCompta||[]).find(p=>p.compte===contrepartie)?.libelle||"",debit:0,credit:montant,tva:0});
    } else {
      // Crédit Caisse (57) / Débit compte de charge ou fournisseur
      ecritures.push({id:crypto.randomUUID(),date:jour,journal_code:"CA",libelle,reference:mvt.reference||libelle,numero_piece:piece,compte_num:caisseCompta,compte_lib:"Caisse",debit:0,credit:montant,tva:0});
      if(contrepartie) ecritures.push({id:crypto.randomUUID(),date:jour,journal_code:"CA",libelle,reference:mvt.reference||libelle,numero_piece:piece,compte_num:contrepartie,compte_lib:(DB.planCompta||[]).find(p=>p.compte===contrepartie)?.libelle||"",debit:montant,credit:0,tva:0});
    }
    for(const e of ecritures){
      const ok=await dbUpsert("journal_entries",e);
      if(ok) (DB.journal=DB.journal||[]).push(e);
    }
    if(ecritures.length) toast("💼 Écriture CA enregistrée dans le journal",1500);
  }
  toast("✅ Mouvement enregistré — Solde : "+Math.round(soldeApres).toLocaleString("fr-FR")+" "+devise);
  const _fc=document.getElementById("fil-caisse")?.value||"";
  const _ft=document.getElementById("fil-mvt-caisse")?.value||"";
  closeOverlays();

  // Proposer impression du reçu
  const co=DB.settings.company||{};
  const recuHtml=[
    "<!DOCTYPE html><html><head><meta charset='utf-8'><style>",
    "*{margin:0;padding:0;box-sizing:border-box}*{-webkit-print-color-adjust:exact!important;print-color-adjust:exact!important;color-adjust:exact!important}body{font-family:Arial,sans-serif;font-size:12px;padding:16px;max-width:300px;margin:auto}",
    ".logo{text-align:center;margin-bottom:8px;font-weight:700;font-size:14px}",
    ".div{border-top:1px dashed #000;margin:8px 0}",
    ".row{display:flex;justify-content:space-between;padding:2px 0}",
    ".title{text-align:center;font-weight:700;font-size:14px;margin:8px 0;text-transform:uppercase}",
    ".amt{text-align:center;font-size:22px;font-weight:700;margin:10px 0;border:2px solid #000;padding:8px}",
    ".footer{text-align:center;font-size:10px;margin-top:10px;color:#555}",
    "</style></head><body>",
    "<div class='logo'>"+(co.name||"Creatis Studio")+"</div>",
    "<div style='text-align:center;font-size:10px'>"+(co.siege||"")+"</div>",
    "<div class='div'></div>",
    "<div class='title'>REÇU DE "+(typeMvt==="entree"?"RECETTE":"DÉPENSE")+"</div>",
    "<div class='div'></div>",
    "<div class='row'><span>Date :</span><span>"+new Date().toLocaleString("fr-FR")+"</span></div>",
    "<div class='row'><span>N° reçu :</span><span>"+mvt.id.slice(-8).toUpperCase()+"</span></div>",
    "<div class='row'><span>Caisse :</span><span>"+(c?.nom||"—")+"</span></div>",
    "<div class='row'><span>Libellé :</span><span>"+esc(libelle)+"</span></div>",
    mvt.reference?"<div class='row'><span>Réf. :</span><span>"+esc(mvt.reference)+"</span></div>":"",
    "<div class='div'></div>",
    "<div class='amt'>"+(typeMvt==="entree"?"+":"−")+" "+Math.round(montant).toLocaleString("fr-FR")+" "+devise+"</div>",
    "<div class='row'><span>Solde avant :</span><span>"+Math.round(solde).toLocaleString("fr-FR")+" "+devise+"</span></div>",
    "<div class='row'><span>Solde après :</span><span style='font-weight:700'>"+Math.round(soldeApres).toLocaleString("fr-FR")+" "+devise+"</span></div>",
    "<div class='div'></div>",
    "<div class='footer'>Merci de conserver ce reçu · "+(co.site||"www.creatis-ci.com")+"</div>",
    "</body></html>"
  ].join("");
  if(confirm("Imprimer le reçu de caisse ?")){
    const w=window.open("","_blank","width=340,height=600");
    if(w){w.document.write(recuHtml);w.document.close();setTimeout(()=>w.print(),300);}
  }

  go("caisses");
  setTimeout(()=>{
    const s1=document.getElementById("fil-caisse"); if(s1&&_fc)s1.value=_fc;
    const s2=document.getElementById("fil-mvt-caisse"); if(s2&&_ft)s2.value=_ft;
    if(_fc||_ft) renderCaisseMvt();
  },60);
}

