function buildBalanceRowsSage(from,to){
  // Sépare : ouverture (AN, antérieure à `from`) vs mouvements de la période
  const openMap={}, mvtMap={};
  const addTo=(map,num,lib,d,c)=>{
    if(!num)return;
    if(!map[num])map[num]={lib,d:0,c:0};
    map[num].d+=+d||0; map[num].c+=+c||0;
    if(lib && !map[num].lib) map[num].lib=lib;
  };

  // Écritures auto UNIQUEMENT (factures + dépenses) — les écritures manuelles
  // (OD/AN) sont dans DB.journal et traitées séparément ci-dessous ; les
  // inclure ici aussi les compterait EN DOUBLE (buildEcritures() les contient déjà)
  buildEcritures().filter(e=>e.source==="auto").forEach(e=>{
    const d=new Date(e.date||0);
    if(d>=from && d<=to) addTo(mvtMap,e.compte,e.compteLib,e.debit,e.credit);
  });
  // Écritures journal (AN + OD manuelles) — seule et unique source pour celles-ci
  (DB.journal||[]).forEach(j=>{
    const d=new Date(j.date||0);
    const num=j.compte_num||j.compte||"";
    if(j.journal_code==="AN"){
      // Toujours traité comme solde d'ouverture, peu importe la date exacte
      addTo(openMap,num,j.compte_lib,j.debit,j.credit);
    } else if(d>=from && d<=to){
      addTo(mvtMap,num,j.compte_lib,j.debit,j.credit);
    }
  });

  // Libellés exacts du plan comptable (priorité)
  const allNums=new Set([...Object.keys(openMap),...Object.keys(mvtMap)]);
  const libOf=(num)=>{
    const p=(DB.planCompta||[]).find(x=>x.compte===num);
    if(p) return p.libelle;
    return (openMap[num]&&openMap[num].lib) || (mvtMap[num]&&mvtMap[num].lib) || "";
  };

  const comptes=[...allNums].sort((a,b)=>a.localeCompare(b));

  // Construction des lignes avec sous-totaux : classe 6 (601/604/605→60,61...)
  // ET comptes tiers 411xxx→TOTAL 411, 401xxx→TOTAL 401 (rattachement auxiliaire→collectif)
  const rows=[];
  const sub3={}, sub2={};
  let curP2=null, curP3=null;
  let curTiers=null;

  const acc=(map,p,key)=>{ map[p]=map[p]||{od:0,oc:0,md:0,mc:0}; };

  const flush3=(p3)=>{
    if(p3 && sub3[p3]) rows.push({type:"subtotal",compte:p3,lib:"TOTAL "+p3,...sub3[p3]});
  };
  const flush2=(p2)=>{
    if(p2 && sub2[p2]) rows.push({type:"subtotal",compte:p2,lib:"TOTAL "+p2,...sub2[p2]});
  };
  const flushTiers=(pt)=>{
    if(pt && sub3[pt]) rows.push({type:"subtotal",compte:pt,lib:"TOTAL "+pt+(pt==="411"?" CLIENTS":pt==="401"?" FOURNISSEURS":""),...sub3[pt]});
  };

  for(const num of comptes){
    const o=openMap[num]||{d:0,c:0}, m=mvtMap[num]||{d:0,c:0};
    if(!o.d&&!o.c&&!m.d&&!m.c) continue;
    const lib=libOf(num);
    const isCharge8 = num.length===8 && num[0]==="6";
    const prefixTiers = num.length===8 && (num.slice(0,3)==="411"||num.slice(0,3)==="401") ? num.slice(0,3) : null;
    const line={type:"detail",compte:num,lib,od:o.d,oc:o.c,md:m.d,mc:m.c};

    if(isCharge8){
      if(curTiers){ flushTiers(curTiers); curTiers=null; }
      const p2=num.slice(0,2), p3=num.slice(0,3);
      if(curP3 && curP3!==p3){ flush3(curP3); }
      if(curP2 && curP2!==p2){ flush2(curP2); }
      curP2=p2; curP3=p3;
      acc(sub3,0,p3); sub3[p3].od+=o.d;sub3[p3].oc+=o.c;sub3[p3].md+=m.d;sub3[p3].mc+=m.c;
      acc(sub2,0,p2); sub2[p2].od+=o.d;sub2[p2].oc+=o.c;sub2[p2].md+=m.d;sub2[p2].mc+=m.c;
      rows.push(line);
    } else if(prefixTiers){
      if(curP3){ flush3(curP3); curP3=null; }
      if(curP2){ flush2(curP2); curP2=null; }
      if(curTiers && curTiers!==prefixTiers){ flushTiers(curTiers); }
      curTiers=prefixTiers;
      acc(sub3,0,prefixTiers); sub3[prefixTiers].od+=o.d;sub3[prefixTiers].oc+=o.c;sub3[prefixTiers].md+=m.d;sub3[prefixTiers].mc+=m.c;
      rows.push(line);
    } else {
      if(curP3){ flush3(curP3); curP3=null; }
      if(curP2){ flush2(curP2); curP2=null; }
      if(curTiers){ flushTiers(curTiers); curTiers=null; }
      rows.push(line);
    }
  }
  if(curP3) flush3(curP3);
  if(curP2) flush2(curP2);
  if(curTiers) flushTiers(curTiers);

  // Soldes cumulés (ouverture + mouvements), nets en colonne D ou C unique
  rows.forEach(r=>{
    const d=(r.od||0)+(r.md||0), c=(r.oc||0)+(r.mc||0);
    if(d>=c){ r.sd=d-c; r.sc=0; } else { r.sd=0; r.sc=c-d; }
  });

  const detailRows=rows.filter(r=>r.type==="detail");
  const bilan=detailRows.filter(r=>r.compte[0]<"6");
  const gestion=detailRows.filter(r=>r.compte[0]>="6");
  const sumOf=(arr,k)=>arr.reduce((s,r)=>s+(r[k]||0),0);
  const sumBD=sumOf(bilan,"md"),   sumBC=sumOf(bilan,"mc");
  const sumGD=sumOf(gestion,"md"), sumGC=sumOf(gestion,"mc");
  const totD=sumBD+sumGD, totC=sumBC+sumGC;

  return {rows, sumBD,sumBC,sumGD,sumGC,totD,totC};
}

/* ============================================================
   BILAN & COMPTE DE RÉSULTAT — Classement SYSCOHADA
   Reclasse la Balance des comptes en Actif/Passif et Produits/Charges
   ============================================================ */
const SOUS_CLASSE_LABELS = {
  "60":"Achats","61":"Transports","62":"Services extérieurs",
  "63":"Autres services extérieurs","64":"Impôts et taxes","65":"Autres charges",
  "66":"Charges de personnel","67":"Charges financières","68":"Dotations aux amortissements","69":"Charges HAO"
};

function buildBilanEtResultat(from,to){
  const {rows}=buildBalanceRowsSage(from,to);
  const detail=rows.filter(r=>r.type==="detail");
  const classeOf=num=>{ const p=(DB.planCompta||[]).find(x=>x.compte===num); return p?p.classe:parseInt(num[0]); };

  let immoBrut=0, amortissements=0, stocks=0, creances=0, tresoActif=0;
  let capitauxPropres=0, dettesCirc=0, tresoPassif=0, autresHAO=0;
  const chargesParSousClasse={}; let produits=0;
  const detailActif=[], detailPassif=[];

  detail.forEach(r=>{
    const cl=classeOf(r.compte);
    const solde=r.sd-r.sc;
    if(cl===1){
      capitauxPropres += (r.sc-r.sd);
      detailPassif.push({compte:r.compte,lib:r.lib,montant:r.sc-r.sd,grp:"Capitaux propres"});
    } else if(cl===2){
      if(String(r.compte||"").startsWith("28")){ amortissements += (r.sc-r.sd); detailActif.push({compte:r.compte,lib:r.lib,montant:-(r.sc-r.sd),grp:"Immobilisations"}); }
      else { immoBrut += (r.sd-r.sc); detailActif.push({compte:r.compte,lib:r.lib,montant:r.sd-r.sc,grp:"Immobilisations"}); }
    } else if(cl===3){
      stocks += (r.sd-r.sc);
      detailActif.push({compte:r.compte,lib:r.lib,montant:r.sd-r.sc,grp:"Stocks"});
    } else if(cl===4){
      if(solde>=0){ creances += solde; detailActif.push({compte:r.compte,lib:r.lib,montant:solde,grp:"Créances"}); }
      else { dettesCirc += -solde; detailPassif.push({compte:r.compte,lib:r.lib,montant:-solde,grp:"Dettes circulantes"}); }
    } else if(cl===5){
      if(solde>=0){ tresoActif += solde; detailActif.push({compte:r.compte,lib:r.lib,montant:solde,grp:"Trésorerie"}); }
      else { tresoPassif += -solde; detailPassif.push({compte:r.compte,lib:r.lib,montant:-solde,grp:"Trésorerie passif"}); }
    } else if(cl===6){
      const sous=String(r.compte||"").slice(0,2);
      chargesParSousClasse[sous]=(chargesParSousClasse[sous]||0)+(r.sd-r.sc);
    } else if(cl===7){
      produits += (r.sc-r.sd);
    } else if(cl===8){
      autresHAO += (r.sd-r.sc);
    }
  });

  const immoNet=immoBrut-amortissements;
  const totalActif=immoNet+stocks+creances+tresoActif;
  const totalCharges=Object.values(chargesParSousClasse).reduce((a,b)=>a+b,0)+autresHAO;
  const resultatNet=produits-totalCharges;
  const totalPassif=capitauxPropres+resultatNet+dettesCirc+tresoPassif;

  return {immoBrut,amortissements,immoNet,stocks,creances,tresoActif,totalActif,
          capitauxPropres,resultatNet,dettesCirc,tresoPassif,totalPassif,
          chargesParSousClasse,totalCharges,produits,autresHAO,detailActif,detailPassif};
}

