// ── Export Excel fiche fiscale ───────────────────────────────────
async function exportFiscaliteExcel(){
  if(!await ensureXLSX()){toast("Module Excel non chargé");return;}
  const y  = new Date().getFullYear();
  const co = DB.settings.company||{};
  const dev= DB.settings.devise||"F CFA";
  const fmt= n=>Math.round(n||0);

  let caTTC=0,caHT=0,depHT=0,tvaCollectee=0,tvaDed=0;
  DB.factures.forEach(f=>{if(new Date(f.date||0).getFullYear()===y){caTTC+=f.montantTTC||0;caHT+=f.montantHT||0;tvaCollectee+=f.montantTVA||0;}});
  DB.depenses.forEach(d=>{if(new Date(d.date||0).getFullYear()===y){depHT+=d.ht||0;tvaDed+=d.tva||0;}});
  const bic=Math.max(0,(caHT-depHT)*0.25);
  const imf=Math.max(400000,caTTC*0.02);
  const impot=Math.max(bic,imf);
  const acompte=Math.round(impot/3);

  const wb=XLSX.utils.book_new();
  const rows=[
    [`Fiche Fiscale — ${co.name||"CREATIS STUDIO"} — Exercice ${y}`,null,null],
    [`Régime : ${co.regime||"RSI"} · Centre : ${co.centre||""} · CC : ${co.cc||""}`],
    [],
    ["COMPTE DE RÉSULTAT",null,null],
    ["Chiffre d'affaires HT","",fmt(caHT)],
    ["Charges déductibles HT","",fmt(depHT)],
    ["Résultat fiscal","",fmt(caHT-depHT)],
    [],
    ["BIC / IMF",null,null],
    ["BIC (25% du bénéfice)","",fmt(bic)],
    ["IMF RSI (2% CA TTC, min 400 000 F)","",fmt(imf)],
    ["Impôt dû MAX(BIC, IMF)","",fmt(impot)],
    [],
    ["ACOMPTES PROVISIONNELS",null,null],
    ["1ʳᵉ fraction (avant 20/04)",`${acompte}`,fmt(acompte)],
    ["2ᵉ fraction (avant 20/07)",`${acompte}`,fmt(acompte)],
    ["3ᵉ fraction (avant 20/09)",`${acompte}`,fmt(acompte)],
    [],
    ["TVA",null,null],
    ["TVA collectée","",fmt(tvaCollectee)],
    ["TVA déductible","",fmt(tvaDed)],
    ["TVA nette à reverser","",fmt(Math.max(0,tvaCollectee-tvaDed))],
  ];
  const ws=XLSX.utils.aoa_to_sheet(rows);
  ws["!cols"]=[{wch:40},{wch:20},{wch:20}];
  XLSX.utils.book_append_sheet(wb,ws,"Fiscalité");
  XLSX.writeFile(wb,`Fiscalite_${co.name||"CRM"}_${y}.xlsx`);
  toast("✅ Fiche fiscale exportée");
}

/* ============================================================
   SUIVI INFOGRAPHISTES
   Vue par designer : projets en cours, BAT, charge de travail
   ============================================================ */
function viewInfographistes(){
  if(!vis("infographistes"))return;
  window._infoOnglet=window._infoOnglet||"suivi";

  const now=new Date();
  const today=now.toISOString().slice(0,10);
  const commandes=DB.commandes||[];
  const actives=commandes.filter(c=>c.statut!=="livré"&&c.statut!=="facturé");
  const nonAssignees=actives.filter(c=>!c.responsableId&&!c.responsable_id);
  const enRetard=actives.filter(c=>c.deadline&&c.deadline<today);
  const batEnAttente=actives.filter(c=>{const b=c.statutBat||c.statut_bat||"";return b==="bat_envoye"||b==="en_revision";});

  // Infographistes = tous les users actifs
  const infos=(DB.users||[]).filter(u=>u.active!==false);

  // Qui travaille EN CE MOMENT (statut_infographiste = "en_cours")
  const enCours=actives.filter(c=>c.statutInfographiste||c.statut_infographiste==="en_cours");

  $("#pg-title").textContent="Suivi Infographistes";
  $("#pg-sub").textContent=`${actives.length} projet(s) actif(s) · ${enCours.length} en production maintenant · ${nonAssignees.length} non assigné(s)`;
  $("#pg-actions").innerHTML=`
    <button class="btn" onclick="window._infoOnglet='suivi';viewInfographistes()" style="border-color:${window._infoOnglet==='suivi'?'var(--cyan)':'var(--ligne)'};color:${window._infoOnglet==='suivi'?'var(--cyan)':'var(--txt-2)'}">📋 Suivi</button>
    <button class="btn" onclick="window._infoOnglet='rendement';viewInfographistes()" style="border-color:${window._infoOnglet==='rendement'?'var(--cyan)':'var(--ligne)'};color:${window._infoOnglet==='rendement'?'var(--cyan)':'var(--txt-2)'}">📊 Rendement</button>
    <button class="btn btn-primary" onclick="assignerTacheModal()">＋ Assigner une tâche</button>
  `;

  // KPIs
  const kpi=`<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(170px,1fr));gap:12px;margin-bottom:16px">
    <div class="card kpi c-cyan" style="padding:14px 16px">
      <div class="lab">Projets actifs</div>
      <div class="val tabnum" style="font-size:22px">${actives.length}</div>
      <div class="delta">${infos.length} infographiste(s)</div>
    </div>
    <div class="card kpi ${enCours.length?"c-ok":"c-noir"}" style="padding:14px 16px">
      <div class="lab">🟢 En production maintenant</div>
      <div class="val tabnum" style="font-size:22px">${enCours.length}</div>
      <div class="delta">${enCours.map(c=>esc(c.numero||"")).slice(0,3).join(", ")||"aucun"}</div>
    </div>
    <div class="card kpi ${nonAssignees.length?"c-jaune":"c-noir"}" style="padding:14px 16px">
      <div class="lab">⚠️ Non assignés</div>
      <div class="val tabnum" style="font-size:22px;color:${nonAssignees.length?"var(--warn)":"inherit"}">${nonAssignees.length}</div>
      <div class="delta">sans infographiste</div>
    </div>
    <div class="card kpi ${enRetard.length?"c-mag":"c-noir"}" style="padding:14px 16px">
      <div class="lab">🔴 En retard</div>
      <div class="val tabnum" style="font-size:22px;color:${enRetard.length?"var(--danger)":"inherit"}">${enRetard.length}</div>
      <div class="delta">deadline dépassée</div>
    </div>
    <div class="card kpi c-mag" style="padding:14px 16px">
      <div class="lab">📤 BAT en attente</div>
      <div class="val tabnum" style="font-size:22px">${batEnAttente.length}</div>
      <div class="delta">envoyé ou en révision</div>
    </div>
  </div>`;

  const onglet=window._infoOnglet||"suivi";
  let contenu="";

  if(onglet==="suivi"){
    contenu=renderSuiviInfos(infos, actives, nonAssignees, now, today);
  } else {
    contenu=renderRendementInfos(infos, commandes, now);
  }

  $("#view").innerHTML=kpi+contenu;
}

/* ── Vue Suivi ─────────────────────────────────────────────── */
function renderSuiviInfos(infos, actives, nonAssignees, now, today){
  const batOrder={non_demarre:0,en_cours:1,bat_envoye:2,en_revision:3,bat_approuve:4,en_impression:5};

  let html=`<div style="display:flex;flex-direction:column;gap:14px">`;

  // 1. Projets non assignés (prioritaire)
  if(nonAssignees.length){
    html+=`<div class="card panel" style="border-left:3px solid var(--warn)">
      <div class="panel-h" style="padding:12px 16px">
        <span style="font-size:18px">⚠️</span>
        <div style="margin-left:8px"><div style="font-weight:700">À assigner (${nonAssignees.length})</div>
          <div style="font-size:11px;color:var(--txt-2)">Ces projets n'ont pas d'infographiste</div></div>
      </div>
      <div style="overflow-x:auto"><table><thead><tr><th>N°</th><th>Projet</th><th>Client</th><th>Deadline</th><th>Statut</th><th></th></tr></thead><tbody>
      ${nonAssignees.map(c=>{
        const late=c.deadline&&c.deadline<today;
        return`<tr>
          <td class="meta tabnum">${esc(c.numero||"")}</td>
          <td><div class="nm">${esc(c.titre)}</div></td>
          <td class="meta">${esc(clientName(c.clientId))}</td>
          <td class="meta" style="color:${late?"var(--danger)":""}">${fdate(c.deadline)}${late?" ⚠️":""}</td>
          <td>${pill(c.statut)}</td>
          <td>${wr("commandes")?`<button class="btn btn-sm btn-primary" onclick="quickAssignModal('${c.id}')">👤 Assigner</button>`:""}</td>
        </tr>`;
      }).join("")}
      </tbody></table></div>
    </div>`;
  }

  // 2. Carte par infographiste
  infos.forEach(u=>{
    const myCmds=actives.filter(c=>(c.responsableId||c.responsable_id)===u.id)
      .sort((a,b)=>{
        const la=a.deadline&&a.deadline<today, lb=b.deadline&&b.deadline<today;
        if(la&&!lb)return -1; if(!la&&lb)return 1;
        return (batOrder[b.statutBat||b.statut_bat||"non_demarre"]||0)-(batOrder[a.statutBat||a.statut_bat||"non_demarre"]||0);
      });

    const enCoursNow=myCmds.filter(c=>(c.statutInfographiste||c.statut_infographiste)==="en_cours");
    const late=myCmds.filter(c=>c.deadline&&c.deadline<today).length;
    const r=roleOf(u);

    // Barre de statut colorée selon activité
    const borderColor=enCoursNow.length?"var(--ok)":late?"var(--danger)":"var(--ligne)";

    html+=`<div class="card panel" style="border-left:3px solid ${borderColor}">
      <div class="panel-h" style="padding:12px 16px">
        <div style="display:flex;align-items:center;gap:10px">
          <div style="width:38px;height:38px;border-radius:50%;background:var(--cyan)18;border:2.5px solid ${borderColor};display:flex;align-items:center;justify-content:center;font-size:15px;font-weight:700;color:var(--cyan);flex-shrink:0">
            ${esc((u.name||"?")[0].toUpperCase())}
          </div>
          <div>
            <div style="font-size:15px;font-weight:700">${esc(u.name||"")}</div>
            <div style="font-size:11px;color:var(--txt-2)">
              ${esc(r?.name||"")}
              ${enCoursNow.length?`<span style="color:var(--ok);font-weight:700;margin-left:6px">🟢 En cours — ${esc(enCoursNow[0].titre||"")}</span>`:"<span style='color:var(--txt-3)'>⚪ Disponible</span>"}
            </div>
          </div>
        </div>
        <div class="spacer"></div>
        <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap">
          <span style="font-size:11px;color:var(--txt-2)">${myCmds.length} projet(s)</span>
          ${wr("users")?`
            <button class="btn btn-sm btn-ghost" onclick="editInfographiste('${u.id}')" title="Modifier le compte">✏️</button>
            <button class="btn btn-sm btn-ghost" onclick="delInfographiste('${u.id}')" title="Désactiver/Supprimer" style="color:var(--danger)">🗑️</button>
          `:""}
          ${late?`<span class="pill p-red" style="font-size:10px">${late} en retard</span>`:""}
          ${["bat_envoye","en_revision","bat_approuve"].map(st=>{
            const n=myCmds.filter(c=>(c.statutBat||c.statut_bat)===st).length;
            return n?batBadge(st).replace("</span>",` ×${n}</span>`):"";
          }).join("")}
        </div>
      </div>
      ${myCmds.length?`<div style="overflow-x:auto"><table><thead><tr>
        <th>N°</th><th>Projet</th><th>Client</th><th>Deadline</th>
        <th>Statut infographiste</th><th>BAT</th><th>Révisions</th><th></th>
      </tr></thead><tbody>
      ${myCmds.map(c=>{
        const isLate=c.deadline&&c.deadline<today;
        const si=c.statutInfographiste||c.statut_infographiste||"assigné";
        const siColor={assigné:"var(--txt-2)",en_cours:"var(--ok)",pause:"var(--warn)",terminé:"var(--cyan)",révisions:"var(--magenta)"}[si]||"var(--txt-2)";
        return`<tr style="${isLate?"background:#fde8e815":""}">
          <td class="meta tabnum">${esc(c.numero||"")}</td>
          <td><div class="nm">${esc(c.titre)}</div>${c.brief?`<div class="meta" style="font-size:10px">${esc(c.brief)}</div>`:""}</td>
          <td class="meta">${esc(clientName(c.clientId))}</td>
          <td class="meta" style="color:${isLate?"var(--danger)":""};font-weight:${isLate?"700":"400"}">${fdate(c.deadline)}${isLate?" ⚠️":""}</td>
          <td>
            <select style="padding:3px 7px;border-radius:6px;font-size:11px;font-weight:600;border:1.5px solid ${siColor};color:${siColor};background:var(--carte);cursor:pointer"
              onchange="setStatutInfographiste('${c.id}',this.value)">
              ${["assigné","en_cours","pause","révisions","terminé"].map(s=>`<option value="${s}" ${si===s?"selected":""}>${{assigné:"📋 Assigné",en_cours:"🟢 En cours",pause:"⏸️ Pause",révisions:"🔄 Révisions",terminé:"✅ Terminé"}[s]||s}</option>`).join("")}
            </select>
          </td>
          <td>${batBadge(c.statutBat||c.statut_bat||"non_demarre")}</td>
          <td style="text-align:center">
            <div style="display:flex;align-items:center;gap:4px;justify-content:center">
              <button onclick="addRevision('${c.id}',-1)" style="padding:1px 5px;border-radius:4px;border:1px solid var(--ligne);background:var(--carte);cursor:pointer;font-size:11px">−</button>
              <span style="font-weight:700;min-width:20px;text-align:center">${c.nbRevisions||c.nb_revisions||0}</span>
              <button onclick="addRevision('${c.id}',1)" style="padding:1px 5px;border-radius:4px;border:1px solid var(--ligne);background:var(--carte);cursor:pointer;font-size:11px">＋</button>
            </div>
          </td>
          <td style="white-space:nowrap">
            ${wr("commandes")?`<button class="btn btn-sm btn-ghost" onclick="quickAssignModal('${c.id}')" title="Réassigner">👤</button>
            <button class="btn btn-sm btn-ghost" onclick="editCmd('${c.id}')" title="Modifier">✏️</button>`:""}</td>
        </tr>`;
      }).join("")}
      </tbody></table></div>`
      :`<div style="padding:12px 16px;color:var(--txt-3);font-size:12px">Aucun projet assigné</div>`}
    </div>`;
  });

  // ── Section tâches libres (non liées à une commande) ──
  const tachesLibres = (DB.activiteInfo||[]).filter(t=>
    t.type_action==="tache" && !t.commande_id &&
    t.statut!=="terminé" && t.statut!=="annulé"
  );
  if(tachesLibres.length){
    html += `<div class="card panel" style="border-left:3px solid var(--mag)">
      <div class="panel-h" style="padding:12px 16px">
        <span style="font-size:18px">✏️</span>
        <div style="margin-left:8px">
          <div style="font-weight:700">Tâches libres (${tachesLibres.length})</div>
          <div style="font-size:11px;color:var(--txt-2)">Non liées à une commande</div>
        </div>
      </div>
      <div style="overflow-x:auto"><table><thead><tr>
        <th>Tâche</th><th>Assigné à</th><th>Type</th><th>Priorité</th><th>Deadline</th><th>Statut</th><th></th>
      </tr></thead><tbody>
      ${tachesLibres.map(t=>{
        const userId = t.user_id;
        const empId  = t.employe_id;
        const user   = userId?(DB.users||[]).find(u=>u.id===userId):null;
        const emp    = empId?(DB.employes||[]).find(e=>e.id===empId):null;
        const assigneeName = user?esc(user.name):emp?esc([emp.prenom,emp.nom].filter(Boolean).join(" ")||emp.nom||"?"):"—";
        const prio   = t.priorite||"normale";
        const prioColor={urgente:"var(--danger)",haute:"var(--warn)",normale:"var(--txt-2)",basse:"var(--cyan)"}[prio]||"var(--txt-2)";
        const prioIc = {urgente:"🔴",haute:"🟡",normale:"⚪",basse:"🔵"}[prio]||"⚪";
        const isLate = t.deadline && t.deadline<today;
        const si = t.statut||"assigné";
        const siColor={assigné:"var(--txt-2)",en_cours:"var(--ok)",pause:"var(--warn)",terminé:"var(--cyan)",révisions:"var(--magenta)"}[si]||"var(--txt-2)";
        return`<tr>
          <td><div class="nm">${esc(t.titre||"—")}</div>${t.notes?`<div class="meta" style="font-size:10px">${esc(t.notes)}</div>`:""}</td>
          <td><div style="display:flex;align-items:center;gap:6px">
            <div style="width:26px;height:26px;border-radius:50%;background:${user?"var(--cyan)":"var(--mag)"}18;border:1.5px solid ${user?"var(--cyan)":"var(--mag)"};display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:700;color:${user?"var(--cyan)":"var(--mag)"}">${assigneeName[0]||"?"}</div>
            <span style="font-size:12px">${assigneeName}</span>
          </div></td>
          <td class="meta">${esc(t.type_travail||"—")}</td>
          <td><span style="font-size:12px;color:${prioColor};font-weight:600">${prioIc} ${prio}</span></td>
          <td class="meta" style="color:${isLate?"var(--danger)":""}">${fdate(t.deadline)}${isLate?" ⚠️":""}</td>
          <td>
            <select style="padding:3px 7px;border-radius:6px;font-size:11px;font-weight:600;border:1.5px solid ${siColor};color:${siColor};background:var(--carte);cursor:pointer"
              onchange="setStatutTache('${t.id}',this.value)">
              ${["assigné","en_cours","pause","révisions","terminé","annulé"].map(s=>`<option value="${s}" ${si===s?"selected":""}>${{assigné:"📋 Assigné",en_cours:"🟢 En cours",pause:"⏸️ Pause",révisions:"🔄 Révisions",terminé:"✅ Terminé",annulé:"✗ Annulé"}[s]||s}</option>`).join("")}
            </select>
          </td>
          <td>
            <button class="btn btn-sm btn-ghost" onclick="assignerTacheModal()" title="Nouvelle tâche">＋</button>
            <button class="btn btn-sm btn-ghost" onclick="terminerTache('${t.id}')" title="Marquer terminée" style="color:var(--ok)">✓</button>
          </td>
        </tr>`;
      }).join("")}
      </tbody></table></div>
    </div>`;
  }

  html+=`</div>`;
  return html;
}

/* ── Vue Rendement ─────────────────────────────────────────── */
function renderRendementInfos(infos, commandes, now){
  const thisMonth=now.getMonth()+"-"+now.getFullYear();
  const inMonth=d=>{if(!d)return false;const dt=new Date(d);return dt.getMonth()+"-"+dt.getFullYear()===thisMonth;};

  let html=`<div style="display:flex;flex-direction:column;gap:14px">
    <div class="card panel">
      <div class="panel-h" style="padding:12px 16px"><h3>📊 Rendement — ${new Date().toLocaleDateString("fr-FR",{month:"long",year:"numeric"})}</h3></div>
      <div style="overflow-x:auto"><table><thead><tr>
        <th>Infographiste</th>
        <th class="r">Projets actifs</th>
        <th class="r">Terminés (mois)</th>
        <th class="r">Moy. révisions</th>
        <th class="r">% dans les délais</th>
        <th class="r">BAT approuvés</th>
        <th>Charge</th>
      </tr></thead><tbody>`;

  infos.forEach(u=>{
    const myCmds=commandes.filter(c=>(c.responsableId||c.responsable_id)===u.id);
    const actives=myCmds.filter(c=>c.statut!=="livré"&&c.statut!=="facturé");
    const terminesMois=myCmds.filter(c=>(c.statut==="livré"||c.statut==="facturé")&&inMonth(c.updatedAt||c.updated_at||c.createdAt||c.created_at));
    const avgRevisions=myCmds.length?Math.round(myCmds.reduce((s,c)=>s+(c.nbRevisions||c.nb_revisions||0),0)/myCmds.length*10)/10:0;
    const dansDelais=myCmds.filter(c=>c.statut==="livré"||c.statut==="facturé").filter(c=>!c.deadline||new Date(c.deadline)>=new Date(c.updatedAt||c.created_at||0));
    const totalTermines=myCmds.filter(c=>c.statut==="livré"||c.statut==="facturé").length;
    const pctDelais=totalTermines?Math.round(dansDelais.length/totalTermines*100):100;
    const batApprouves=myCmds.filter(c=>(c.statutBat||c.statut_bat)==="bat_approuve"||(c.statutBat||c.statut_bat)==="en_impression").length;

    // Barre de charge (max 6 projets = 100%)
    const chargeP=Math.min(100,Math.round(actives.length/6*100));
    const chargeColor=chargeP>=100?"var(--danger)":chargeP>=70?"var(--warn)":"var(--ok)";

    html+=`<tr>
      <td><div style="display:flex;align-items:center;gap:8px">
        <div style="width:30px;height:30px;border-radius:50%;background:var(--cyan)18;border:2px solid var(--cyan);display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;color:var(--cyan);flex-shrink:0">${(u.name||"?")[0].toUpperCase()}</div>
        <span style="font-weight:600">${esc(u.name||"")}</span>
      </div></td>
      <td class="r tabnum" style="font-weight:700">${actives.length}</td>
      <td class="r tabnum">${terminesMois.length}</td>
      <td class="r tabnum">${avgRevisions}</td>
      <td class="r" style="color:${pctDelais>=80?"var(--ok)":pctDelais>=60?"var(--warn)":"var(--danger)"};font-weight:700">${pctDelais}%</td>
      <td class="r tabnum">${batApprouves}</td>
      <td style="min-width:100px">
        <div style="background:var(--ligne-2);border-radius:4px;height:8px;overflow:hidden">
          <div style="width:${chargeP}%;height:100%;background:${chargeColor};border-radius:4px;transition:.3s"></div>
        </div>
        <div style="font-size:10px;color:var(--txt-3);margin-top:2px">${actives.length}/6 projets</div>
      </td>
    </tr>`;
  });

  html+=`</tbody></table></div></div></div>`;
  return html;
}

/* ── Actions ───────────────────────────────────────────────── */
function setStatutTache(id, statut){
  const t=(DB.activiteInfo||[]).find(x=>x.id===id);if(!t)return;
  t.statut=statut; t.statut_apres=statut;
  dbUpsert("crm_activite_infographiste",{id,statut,statut_apres:statut}).catch(e=>console.error(e));
}

function terminerTache(id){
  const t=(DB.activiteInfo||[]).find(x=>x.id===id);if(!t)return;
  t.statut="terminé"; t.statut_apres="terminé";
  dbUpsert("crm_activite_infographiste",{id,statut:"terminé",statut_apres:"terminé"}).catch(e=>console.error(e));
  toast("✅ Tâche marquée terminée");
  // Retirer du DOM
  const rows=document.querySelectorAll("button[onclick*=\"terminerTache('"+id+"')\"]");
  rows.forEach(b=>{const tr=b.closest("tr");if(tr)tr.remove();});
}


function setStatutInfographiste(cmdId, statut){
  const c=DB.commandes.find(x=>x.id===cmdId);if(!c)return;
  const old=c.statutInfographiste||c.statut_infographiste||"assigné";
  c.statutInfographiste=statut;
  // Log dans activité
  const log={id:uid(),commande_id:cmdId,user_id:USER?.id||"",type_action:"statut_infographiste",statut_avant:old,statut_apres:statut,commentaire:"",created_at:new Date().toISOString()};
  (DB.activiteInfo=DB.activiteInfo||[]).push(log);
  dbUpsert("crm_activite_infographiste",log).catch(e=>console.error(e));
  dbUpdate("commandes",cmdId,{statut_infographiste:statut}).catch(e=>console.error(e));
  // Rafraîchir l'affichage
  setTimeout(()=>renderSuiviRefresh(),100);
}

function renderSuiviRefresh(){
  // Rafraîchissement léger sans recharger les données
  const now=new Date();
  const today=now.toISOString().slice(0,10);
  const commandes=DB.commandes||[];
  const actives=commandes.filter(c=>c.statut!=="livré"&&c.statut!=="facturé");
  const infos=(DB.users||[]).filter(u=>u.active!==false);
  const nonAssignees=actives.filter(c=>!c.responsableId&&!c.responsable_id);
  const el=document.getElementById("view");
  if(el&&window._infoOnglet==="suivi"){
    const kpi=el.querySelector(".grid.kpis");
    if(!kpi) return viewInfographistes();
    // Juste mettre à jour le contenu
    const after=el.innerHTML.indexOf('</div><div style="display:flex;flex-direction:column');
    if(after<0) return viewInfographistes();
    const newContent=renderSuiviInfos(infos,actives,nonAssignees,now,today);
    const parts=el.innerHTML.split('<div style="display:flex;flex-direction:column');
    if(parts.length>1) el.innerHTML=parts[0]+'<div style="display:flex;flex-direction:column'+newContent.slice(newContent.indexOf('<div style="display:flex;flex-direction:column')+49);
    else viewInfographistes();
  }
}

function addRevision(cmdId, delta){
  const c=DB.commandes.find(x=>x.id===cmdId);if(!c)return;
  const current=c.nbRevisions||c.nb_revisions||0;
  const next=Math.max(0,current+delta);
  c.nbRevisions=next;c.nb_revisions=next;
  dbUpdate("commandes",cmdId,{nb_revisions:next}).catch(e=>console.error(e));
  // Mettre à jour l'affichage
  const el=document.querySelector(`button[onclick="addRevision('${cmdId}',1)"]`);
  if(el){const span=el.previousElementSibling;if(span)span.textContent=next;}
  const el2=document.querySelector(`button[onclick="addRevision('${cmdId}',-1)"]`);
  if(el2){const span=el2.nextElementSibling;if(span)span.textContent=next;}
}

function quickAssignModal(cmdId){
  const c=DB.commandes.find(x=>x.id===cmdId);if(!c)return;
  const infos=(DB.users||[]).filter(u=>u.active!==false);
  const current=c.responsableId||c.responsable_id||"";
  const opts=infos.map(u=>`<label style="display:flex;align-items:center;gap:10px;padding:8px 12px;border-radius:8px;cursor:pointer;border:1.5px solid ${current===u.id?"var(--cyan)":"var(--ligne)"};margin-bottom:6px;background:${current===u.id?"var(--cyan)08":"var(--carte)"}">
    <input type="radio" name="assignee" value="${u.id}" ${current===u.id?"checked":""} style="display:none">
    <div style="width:32px;height:32px;border-radius:50%;background:var(--cyan)18;border:2px solid var(--cyan);display:flex;align-items:center;justify-content:center;font-weight:700;color:var(--cyan)">${(u.name||"?")[0]}</div>
    <div>
      <div style="font-weight:600">${esc(u.name)}</div>
      <div style="font-size:11px;color:var(--txt-2)">${esc(roleOf(u)?.name||"")}</div>
    </div>
    <div class="spacer"></div>
    ${current===u.id?`<span class="pill p-cyan" style="font-size:10px">Assigné</span>`:""}
  </label>`).join("");

  modal(`<h2>👤 Assigner — ${esc(c.titre)}</h2>
    <p style="color:var(--txt-2);margin-top:4px;font-size:12px">${esc(clientName(c.clientId))} · ${fdate(c.deadline)}</p>
    <div style="margin-top:16px">${opts}</div>
    <label style="display:flex;align-items:center;gap:10px;padding:8px 12px;border-radius:8px;cursor:pointer;border:1.5px solid var(--ligne);background:var(--carte)">
      <input type="radio" name="assignee" value="" ${!current?"checked":""} style="display:none">
      <div style="width:32px;height:32px;border-radius:50%;background:var(--ligne);display:flex;align-items:center;justify-content:center">—</div>
      <span style="color:var(--txt-3)">Aucun (non assigné)</span>
    </label>
    <div class="modal-actions">
      <button class="btn" onclick="closeOverlays()">Annuler</button>
      <button class="btn btn-primary" onclick="doQuickAssign('${cmdId}')">✅ Confirmer</button>
    </div>`);
}

/* ============================================================
   ASSIGNER UNE TÂCHE — Formulaire central
   Commande existante OU tâche libre
   Assignation à un User (CRM) OU un Employé (RH)
   ============================================================ */

function assignerTacheModal(prefillCmdId){
  const commandes  = (DB.commandes||[]).filter(c=>c.statut!=="livré"&&c.statut!=="facturé");
  const users      = (DB.users||[]).filter(u=>u.active!==false);
  const employes   = (DB.employes||[]).filter(e=>statutEmp(e)!=="inactif");

  // Tâches existantes (depuis crm_activite_infographiste, type tache)
  const taches = (DB.activiteInfo||[]).filter(t=>t.type_action==="tache"&&t.statut!=="terminé"&&t.statut!=="annulé");

  // Groupes commandes: non assignées d'abord
  const nonAssignees = commandes.filter(c=>!c.responsableId&&!c.responsable_id);
  const assignees    = commandes.filter(c=> c.responsableId|| c.responsable_id);

  const cmdOpts = [
    `<option value="">— Sélectionner une commande —</option>`,
    nonAssignees.length ? `<optgroup label="⚠️ Non assignées (${nonAssignees.length})">`+
      nonAssignees.map(c=>`<option value="${c.id}" ${c.id===prefillCmdId?"selected":""}>[${esc(c.numero||"")}] ${esc(c.titre)} — ${esc(clientName(c.clientId))}</option>`).join("")+
      `</optgroup>` : "",
    assignees.length ? `<optgroup label="Déjà assignées (${assignees.length})">`+
      assignees.map(c=>`<option value="${c.id}" ${c.id===prefillCmdId?"selected":""}>[${esc(c.numero||"")}] ${esc(c.titre)} — ${esc(clientName(c.clientId))}</option>`).join("")+
      `</optgroup>` : "",
  ].join("");

  // Tous les assignables (users + employés)
  const buildPersonneCards = (selected="", type="user") => {
    let html = `<div style="display:flex;flex-direction:column;gap:6px" id="personne-cards">`;

    if(users.length){
      html += `<div style="font-size:11px;font-weight:700;color:var(--txt-2);text-transform:uppercase;letter-spacing:.06em;margin-top:4px;margin-bottom:2px">Comptes CRM</div>`;
      users.forEach(u=>{
        const r = roleOf(u);
        const active = selected===u.id && type==="user";
        html += `<label onclick="selectPersonne('${u.id}','user')" style="display:flex;align-items:center;gap:10px;padding:8px 12px;border-radius:8px;cursor:pointer;border:1.5px solid ${active?"var(--cyan)":"var(--ligne)"};background:${active?"var(--cyan)08":"var(--carte)"};transition:.15s">
          <input type="radio" name="assigneeId" value="user:${u.id}" ${active?"checked":""} style="display:none">
          <div style="width:34px;height:34px;border-radius:50%;background:var(--cyan)18;border:2px solid ${active?"var(--cyan)":"var(--ligne)"};display:flex;align-items:center;justify-content:center;font-size:13px;font-weight:700;color:var(--cyan);flex-shrink:0">${(u.name||"?")[0].toUpperCase()}</div>
          <div style="flex:1">
            <div style="font-weight:600;font-size:13px">${esc(u.name)}</div>
            <div style="font-size:11px;color:var(--txt-2)">${esc(r?.name||"Utilisateur CRM")}</div>
          </div>
          ${active?`<span class="pill p-cyan" style="font-size:10px">✓ Sélectionné</span>`:""}
        </label>`;
      });
    }

    if(employes.length){
      html += `<div style="font-size:11px;font-weight:700;color:var(--txt-2);text-transform:uppercase;letter-spacing:.06em;margin-top:10px;margin-bottom:2px">Équipe (employés)</div>`;
      employes.forEach(e=>{
        const active = selected===e.id && type==="employe";
        const name = [e.prenom,e.nom].filter(Boolean).join(" ")||e.nom||"?";
        html += `<label onclick="selectPersonne('${e.id}','employe')" style="display:flex;align-items:center;gap:10px;padding:8px 12px;border-radius:8px;cursor:pointer;border:1.5px solid ${active?"var(--mag)":"var(--ligne)"};background:${active?"var(--mag)08":"var(--carte)"};transition:.15s">
          <input type="radio" name="assigneeId" value="employe:${e.id}" ${active?"checked":""} style="display:none">
          <div style="width:34px;height:34px;border-radius:50%;background:var(--mag)18;border:2px solid ${active?"var(--mag)":"var(--ligne)"};display:flex;align-items:center;justify-content:center;font-size:13px;font-weight:700;color:var(--mag);flex-shrink:0">${name[0].toUpperCase()}</div>
          <div style="flex:1">
            <div style="font-weight:600;font-size:13px">${esc(name)}</div>
            <div style="font-size:11px;color:var(--txt-2)">${esc(e.poste||e.departement||"Employé")}</div>
          </div>
          ${active?`<span class="pill p-mag" style="font-size:10px">✓ Sélectionné</span>`:""}
        </label>`;
      });
    }

    html += `</div>`;
    return html;
  };

  modal(`
  <div style="display:flex;align-items:center;gap:10px;margin-bottom:4px">
    <div style="width:36px;height:36px;border-radius:10px;background:var(--cyan)14;display:flex;align-items:center;justify-content:center;flex-shrink:0">
      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="var(--cyan)" stroke-width="2"><path d="M9 2h6a1 1 0 0 1 1 1v2H8V3a1 1 0 0 1 1-1z"/><rect x="5" y="4" width="14" height="18" rx="2"/><path d="M9 12h6M9 16h4"/></svg>
    </div>
    <h2 style="margin:0;font-size:17px">Assigner une tâche</h2>
  </div>
  <p style="font-size:12.5px;color:var(--txt-2);margin:6px 0 18px;line-height:1.5">Liez la tâche à une commande existante ou créez-en une libre, puis choisissez à qui l'assigner.</p>

  <!-- Onglet Source -->
  <div style="display:flex;gap:4px;margin-bottom:16px;background:var(--papier);border-radius:9px;padding:3px">
    <button id="src-cmd-btn" onclick="switchSrcTache('cmd')" style="flex:1;padding:8px 6px;border-radius:7px;border:none;cursor:pointer;font-size:12.5px;font-weight:600;background:var(--carte);color:var(--cyan);box-shadow:0 1px 3px rgba(0,0,0,.08);transition:.15s">📂 Commande existante</button>
    <button id="src-libre-btn" onclick="switchSrcTache('libre')" style="flex:1;padding:8px 6px;border-radius:7px;border:none;cursor:pointer;font-size:12.5px;font-weight:600;background:transparent;color:var(--txt-2);transition:.15s">✏️ Tâche libre</button>
  </div>

  <!-- Source Commande -->
  <div id="src-cmd-panel">
    <div class="field" style="margin-bottom:12px">
      <label>Commande à assigner</label>
      <select id="tache-cmd-id" style="font-size:12.5px" onchange="onSelectCmd(this.value)">
        ${cmdOpts}
      </select>
    </div>
    <div id="cmd-preview" style="display:none;padding:10px 12px;border-radius:9px;background:var(--cyan)08;border:1px solid var(--cyan)25;font-size:12.5px;margin-bottom:4px"></div>
  </div>

  <!-- Source Tâche libre -->
  <div id="src-libre-panel" style="display:none">
    <div class="field" style="margin-bottom:12px">
      <label>Titre de la tâche <span style="color:var(--danger)">*</span></label>
      <input id="tache-titre" placeholder="ex : Retouche logo pour client X" style="font-weight:600">
    </div>
    <div class="row2">
      <div class="field">
        <label>Type de travail</label>
        <select id="tache-type">
          ${["Création","Retouche","Mise en page","Maquette BAT","Impression","Finition","Livraison","Autre"].map(t=>`<option>${t}</option>`).join("")}
        </select>
      </div>
      <div class="field">
        <label>Deadline</label>
        <input id="tache-deadline" type="date" value="">
      </div>
    </div>
  </div>

  <div style="height:1px;background:var(--ligne);margin:16px 0"></div>

  <!-- Priorité + Statut -->
  <div class="field" style="margin-bottom:14px">
    <label>Priorité</label>
    <div style="display:grid;grid-template-columns:repeat(2,1fr);gap:8px" id="prio-btns">
      ${[["urgente","Urgente","var(--danger)"],["haute","Haute","var(--warn)"],["normale","Normale","var(--txt-2)"],["basse","Basse","var(--cyan)"]].map(([v,lab,col])=>`
      <label style="display:flex;align-items:center;gap:8px;cursor:pointer;padding:9px 12px;border-radius:9px;border:1.5px solid ${v==="normale"?"var(--cyan)":"var(--ligne)"};background:${v==="normale"?"var(--cyan)08":"var(--carte)"};font-size:12.5px;font-weight:600;transition:.15s">
        <input type="radio" name="tache-prio" value="${v}" ${v==="normale"?"checked":""} style="display:none" onchange="refreshPrioBtns()">
        <span style="width:10px;height:10px;border-radius:50%;background:${col};flex-shrink:0"></span>
        ${lab}
      </label>`).join("")}
    </div>
  </div>

  <div class="field" style="margin-bottom:16px">
    <label>Statut initial</label>
    <select id="tache-statut">
      <option value="assigné">📋 Assigné</option>
      <option value="en_cours">🟢 En cours maintenant</option>
    </select>
  </div>

  <div class="field" style="margin-bottom:18px">
    <label>Notes / Instructions</label>
    <textarea id="tache-notes" rows="2" placeholder="Instructions spéciales, fichiers à utiliser…"></textarea>
  </div>

  <!-- Sélection personne -->
  <div style="font-size:13px;font-weight:700;margin-bottom:8px">Assigner à</div>
  <div style="max-height:220px;overflow-y:auto;border:1.5px solid var(--ligne);border-radius:10px;padding:8px 4px;background:var(--papier)">
    ${buildPersonneCards()}
  </div>

  <div class="modal-actions">
    <button class="btn" onclick="closeOverlays()">Annuler</button>
    <button class="btn btn-primary" onclick="doAssignerTache()" style="min-width:160px">✅ Assigner la tâche</button>
  </div>`);

  // Init
  if(prefillCmdId) onSelectCmd(prefillCmdId);
}

// Sélection visuelle personne
function selectPersonne(id, type){
  window._assigneeId = id;
  window._assigneeType = type;
  // Refresh visuel des cartes
  document.querySelectorAll("#personne-cards label").forEach(lbl=>{
    const inp = lbl.querySelector("input[type=radio]");
    if(!inp) return;
    const [t,i] = inp.value.split(":");
    const active = i===id && t===type;
    const color = t==="user"?"var(--cyan)":"var(--mag)";
    lbl.style.borderColor = active ? color : "var(--ligne)";
    lbl.style.background  = active ? (t==="user"?"var(--cyan)":"var(--mag)")+"08" : "var(--carte)";
    const badge = lbl.querySelector(".pill");
    if(badge) badge.remove();
    if(active){
      const b=document.createElement("span");
      b.className="pill "+(t==="user"?"p-cyan":"p-mag");
      b.style.fontSize="10px";
      b.textContent="✓ Sélectionné";
      lbl.appendChild(b);
    }
    if(active) inp.checked=true;
  });
}

// Switcher source
function switchSrcTache(src){
  const isCmd = src==="cmd";
  document.getElementById("src-cmd-panel").style.display  = isCmd?"":"none";
  document.getElementById("src-libre-panel").style.display = isCmd?"none":"";
  const btn1 = document.getElementById("src-cmd-btn");
  const btn2 = document.getElementById("src-libre-btn");
  if(btn1){btn1.style.background=isCmd?"var(--carte)":"transparent";btn1.style.color=isCmd?"var(--cyan)":"var(--txt-2)";btn1.style.boxShadow=isCmd?"0 1px 3px rgba(0,0,0,.1)":"";}
  if(btn2){btn2.style.background=isCmd?"transparent":"var(--carte)";btn2.style.color=isCmd?"var(--txt-2)":"var(--cyan)";btn2.style.boxShadow=isCmd?"":"0 1px 3px rgba(0,0,0,.1)";}
  window._tacheSrc = src;
}

// Preview commande sélectionnée
function onSelectCmd(cmdId){
  const prev = document.getElementById("cmd-preview");
  if(!prev) return;
  if(!cmdId){prev.style.display="none";return;}
  const c = (DB.commandes||[]).find(x=>x.id===cmdId);
  if(!c){prev.style.display="none";return;}
  const assigned = c.responsableId||c.responsable_id;
  const user = assigned ? (DB.users||[]).find(u=>u.id===assigned) : null;
  prev.style.display = "";
  prev.innerHTML = `
    <div style="display:flex;gap:12px;align-items:center">
      <div style="flex:1">
        <div style="font-weight:700">${esc(c.titre||"")}</div>
        <div style="color:var(--txt-2)">${esc(clientName(c.clientId))} · ${fdate(c.deadline)}</div>
        ${c.brief?`<div style="color:var(--txt-3);font-size:10px;margin-top:2px">${esc(c.brief)}</div>`:""}
      </div>
      <div>
        ${pill(c.statut)}
        ${user?`<div style="font-size:10px;color:var(--txt-2);margin-top:4px">Actuellement : ${esc(user.name)}</div>`:"<div style='font-size:10px;color:var(--warn)'>Non assignée</div>"}
      </div>
    </div>`;
}

function refreshPrioBtns(){
  document.querySelectorAll("#prio-btns label").forEach(lbl=>{
    const inp = lbl.querySelector("input");
    if(!inp) return;
    const active = inp.checked;
    const colors = {urgente:"var(--danger)",haute:"var(--warn)",normale:"var(--txt-2)",basse:"var(--cyan)"};
    const col = colors[inp.value]||"var(--cyan)";
    lbl.style.borderColor = active ? col : "var(--ligne)";
    lbl.style.background  = active ? col+"10" : "var(--carte)";
  });
}

async function doAssignerTache(){
  const src = window._tacheSrc || "cmd";
  const assigneeId   = window._assigneeId || (document.querySelector('input[name="assigneeId"]:checked')?.value||"").split(":")[1];
  const assigneeType = window._assigneeType || (document.querySelector('input[name="assigneeId"]:checked')?.value||"").split(":")[0];

  if(!assigneeId){toast("Sélectionnez une personne");return;}

  const priorite = document.querySelector('input[name="tache-prio"]:checked')?.value||"normale";
  const statut   = document.getElementById("tache-statut")?.value||"assigné";
  const notes    = document.getElementById("tache-notes")?.value?.trim()||"";

  if(src==="cmd"){
    // ── Assignation d'une commande ──────────────────────────
    const cmdId = document.getElementById("tache-cmd-id")?.value;
    if(!cmdId){toast("Sélectionnez une commande");return;}
    const c = (DB.commandes||[]).find(x=>x.id===cmdId);
    if(!c) return;

    // MAJ la commande si c'est un user CRM
    if(assigneeType==="user"){
      c.responsableId  = assigneeId;
      c.responsable_id = assigneeId;
      c.statutInfographiste = statut;
      await dbUpdate("commandes", cmdId, {responsable_id:assigneeId, statut_infographiste:statut});
    }

    // Log dans activiteInfo
    const log = {
      id:uid(), commande_id:cmdId,
      user_id:     assigneeType==="user"    ? assigneeId : (USER?.id||""),
      employe_id:  assigneeType==="employe" ? assigneeId : null,
      type_action: "tache",
      titre:       c.titre||c.numero||"",
      type_travail:document.getElementById("tache-type")?.value||"",
      priorite, statut, notes,
      deadline:    document.getElementById("tache-deadline")?.value||null,
      statut_avant:null, statut_apres:statut,
      commentaire: JSON.stringify({src:"commande", cmdId, priorite}),
      created_at:  new Date().toISOString()
    };
    (DB.activiteInfo=DB.activiteInfo||[]).push(log);
    await dbUpsert("crm_activite_infographiste", log);

    const assigneeName = assigneeType==="user"
      ? (DB.users||[]).find(u=>u.id===assigneeId)?.name||""
      : [((DB.employes||[]).find(e=>e.id===assigneeId)||{}).prenom,
         ((DB.employes||[]).find(e=>e.id===assigneeId)||{}).nom].filter(Boolean).join(" ");

    toast(`✅ "${esc(c.titre||"")}" assignée à ${assigneeName}`);

  } else {
    // ── Tâche libre ─────────────────────────────────────────
    const titre = document.getElementById("tache-titre")?.value?.trim();
    if(!titre){toast("Titre de la tâche requis");return;}
    const type_travail = document.getElementById("tache-type")?.value||"";
    const deadline     = document.getElementById("tache-deadline")?.value||null;

    const log = {
      id:uid(), commande_id:null,
      user_id:     assigneeType==="user"    ? assigneeId : (USER?.id||""),
      employe_id:  assigneeType==="employe" ? assigneeId : null,
      type_action: "tache",
      titre, type_travail, priorite, statut, notes, deadline,
      statut_avant:null, statut_apres:statut,
      commentaire: JSON.stringify({src:"libre", priorite}),
      created_at:  new Date().toISOString()
    };
    (DB.activiteInfo=DB.activiteInfo||[]).push(log);
    await dbUpsert("crm_activite_infographiste", log);

    const assigneeName = assigneeType==="user"
      ? (DB.users||[]).find(u=>u.id===assigneeId)?.name||""
      : [((DB.employes||[]).find(e=>e.id===assigneeId)||{}).prenom,
         ((DB.employes||[]).find(e=>e.id===assigneeId)||{}).nom].filter(Boolean).join(" ");

    toast(`✅ Tâche "${titre}" créée et assignée à ${assigneeName}`);
  }

  window._assigneeId = null;
  window._assigneeType = null;
  window._tacheSrc = null;
  closeOverlays();
  viewInfographistes();
}


/* ── Gestion des infographistes directement depuis la section Suivi ── */
function editInfographiste(id){
  window._userReturnTo="infographistes";
  editUser(id);
}

function delInfographiste(id){
  window._userReturnTo="infographistes";
  delUser(id);
}

function addInfographisteModal(){
  window._userReturnTo="infographistes";
  // Employés RH actifs qui n'ont pas encore de compte CRM (pas de login existant avec ce nom)
  const employesActifs = (DB.employes||[]).filter(e=>statutEmp(e)!=="inactif");
  const usersLoginSet = new Set((DB.users||[]).map(u=>(u.name||"").toLowerCase().trim()));
  const employesSansCompte = employesActifs.filter(e=>{
    const full=[e.prenom,e.nom].filter(Boolean).join(" ").toLowerCase().trim();
    return full && !usersLoginSet.has(full);
  });

  if(!employesSansCompte.length){
    // Aucun employé disponible → aller directement à la création de compte
    editUser();
    return;
  }

  modal(`
  <h2 style="margin-bottom:4px">Ajouter un infographiste</h2>
  <p style="font-size:12.5px;color:var(--txt-2);margin:6px 0 16px;line-height:1.5">Choisissez un employé déjà enregistré dans les Ressources Humaines, ou créez un compte pour une personne externe.</p>

  <div style="font-size:11px;font-weight:700;color:var(--txt-2);text-transform:uppercase;letter-spacing:.06em;margin-bottom:8px">Employés RH disponibles</div>
  <div style="max-height:260px;overflow-y:auto;display:flex;flex-direction:column;gap:6px;margin-bottom:16px">
    ${employesSansCompte.map(e=>{
      const full=[e.prenom,e.nom].filter(Boolean).join(" ");
      return `<label onclick="closeOverlays();prefillUserFromEmploye('${e.id}')" style="display:flex;align-items:center;gap:10px;padding:9px 12px;border-radius:9px;cursor:pointer;border:1.5px solid var(--ligne);background:var(--carte);transition:.15s">
        <div style="width:32px;height:32px;border-radius:50%;background:var(--mag)18;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;color:var(--mag);flex-shrink:0">${(full[0]||"?").toUpperCase()}</div>
        <div style="flex:1">
          <div style="font-weight:600;font-size:13px">${esc(full)}</div>
          <div style="font-size:11px;color:var(--txt-2)">${esc(e.poste||e.departement||"Employé")}</div>
        </div>
        <span class="linkish" style="font-size:11.5px">Choisir →</span>
      </label>`;
    }).join("")}
  </div>

  <div style="height:1px;background:var(--ligne);margin:4px 0 14px"></div>

  <button class="btn" style="width:100%;justify-content:center" onclick="closeOverlays();editUser()">➕ Nouveau compte (personne externe)</button>

  <div class="modal-actions">
    <button class="btn" onclick="closeOverlays()">Annuler</button>
  </div>`);
}

// Pré-remplit le formulaire de création de compte avec les infos d'un employé RH existant
function prefillUserFromEmploye(employeId){
  const e=(DB.employes||[]).find(x=>x.id===employeId);
  if(!e){editUser();return;}
  const full=[e.prenom,e.nom].filter(Boolean).join(" ");
  const loginSuggere=(e.prenom||"").toLowerCase().trim()+"."+(e.nom||"").toLowerCase().trim().replace(/\s+/g,"");
  editUser();
  setTimeout(()=>{
    const nameEl=document.querySelector("#f-user input[name=\"name\"]");
    const loginEl=document.querySelector("#f-user input[name=\"login\"]");
    if(nameEl) nameEl.value=full;
    if(loginEl) loginEl.value=loginSuggere;
  },30);
}


function doQuickAssign(cmdId){
  const sel=document.querySelector('input[name="assignee"]:checked');
  if(!sel){closeOverlays();return;}
  const userId=sel.value;
  const c=DB.commandes.find(x=>x.id===cmdId);if(!c)return;
  c.responsableId=userId||null;
  c.responsable_id=userId||null;
  if(userId&&!c.statutInfographiste){c.statutInfographiste="assigné";}
  const patch={responsable_id:userId||null,statut_infographiste:userId?c.statutInfographiste||"assigné":null};
  dbUpdate("commandes",cmdId,patch).catch(e=>console.error(e));
  closeOverlays();
  toast(userId?"✅ Assigné à "+((DB.users||[]).find(u=>u.id===userId)?.name||""):"Désassigné");
  viewInfographistes();
}

// Changer rapidement le statut BAT depuis le tableau infographistes
function changerBat(cmdId){
  if(!wr("commandes"))return;
  const c=DB.commandes.find(x=>x.id===cmdId); if(!c)return;
  const opts=[["non_demarre","⚪ Pas démarré"],["en_cours","🎨 En création"],
    ["bat_envoye","📤 BAT envoyé"],["en_revision","🔄 Révisions"],
    ["bat_approuve","✅ BAT approuvé"],["en_impression","🖨️ En impression"]];
  modal(`<h2>Changer le statut BAT</h2>
  <div style="font-size:13px;font-weight:600;margin-bottom:12px">${esc(c.titre||"")}</div>
  <div style="display:flex;flex-direction:column;gap:8px">
    ${opts.map(([v,l])=>`
    <button onclick="setBat('${cmdId}','${v}')" style="padding:10px 16px;border-radius:8px;border:2px solid ${(c.statutBat||c.statut_bat||"non_demarre")===v?"var(--cyan)":"var(--ligne)"};background:${(c.statutBat||c.statut_bat||"non_demarre")===v?"var(--cyan)18":"var(--carte)"};text-align:left;cursor:pointer;font-size:13px;font-weight:${(c.statutBat||c.statut_bat||"non_demarre")===v?"700":"400"}">
      ${l}
    </button>`).join("")}
  </div>
  <div class="modal-actions"><button class="btn" onclick="closeOverlays()">Annuler</button></div>`);
}

function setBat(cmdId, newStat){
  const c=DB.commandes.find(x=>x.id===cmdId); if(!c)return;
  c.statutBat=newStat; c.statut_bat=newStat;
  sync("commandes",c);
  toast(`✅ BAT mis à jour : ${BAT_LABELS[newStat]||newStat}`);
  closeOverlays();
  go("infographistes");
}

