// ── SAISIE OD (écriture manuelle) ───────────────────────────────
function openSaisieCompta(opts){
  if(!wr("compta"))return;
  // Tous les comptes de détail + sous-comptes tiers
  const plan=(DB.planCompta||[]).filter(p=>p.actif!==false).sort((a,b)=>a.compte.localeCompare(b.compte));
  const planDetail=plan.filter(p=>p.type_compte==="detail");
  const buildOpts=()=>planDetail.map(p=>{
    const _pc=String(p.compte||"");
    const isTiers=(_pc.startsWith("4111")&&_pc!=="41110000")||(_pc.startsWith("4011")&&_pc!=="40110000");
    return`<option value="${p.compte}">${isTiers?"  ↳ ":""}${p.compte} — ${p.libelle}</option>`;
  }).join("");

  // Lignes initiales
  window._odLignes=(opts&&opts.lignes&&opts.lignes.length)?JSON.parse(JSON.stringify(opts.lignes)):[
    {compte:"",libelle:"",debit:0,credit:0},
    {compte:"",libelle:"",debit:0,credit:0}
  ];

  const renderOdLignes=()=>{
    const optHtml=buildOpts();
    const tbody=document.getElementById("od-tbody");if(!tbody)return;
    tbody.innerHTML=window._odLignes.map((l,i)=>{
      // Tiers lié
      const tiers=getTiersFromCompte(l.compte);
      return`<tr id="od-tr-${i}">
        <td style="padding:4px 6px">
          <input list="od-plan-${i}" value="${esc(l.compte)}" placeholder="N° compte"
            style="width:130px;font-family:monospace;font-size:11px"
            oninput="updOdLigne(${i},'compte',this.value)">
          <datalist id="od-plan-${i}">${optHtml}</datalist>
          ${tiers?`<div style="font-size:10px;color:var(--cyan);margin-top:2px">${tiers}</div>`:""}
        </td>
        <td style="padding:4px 6px">
          <input value="${esc(l.libelle)}" placeholder="Libellé ligne (optionnel)"
            style="width:100%;font-size:11px"
            oninput="updOdLigne(${i},'libelle',this.value)">
        </td>
        <td style="padding:4px 6px">
          <input type="number" step="1" min="0" value="${l.debit||""}" placeholder="0"
            style="width:100px;font-size:11px;text-align:right"
            oninput="updOdLigne(${i},'debit',+this.value||0)">
        </td>
        <td style="padding:4px 6px">
          <input type="number" step="1" min="0" value="${l.credit||""}" placeholder="0"
            style="width:100px;font-size:11px;text-align:right"
            oninput="updOdLigne(${i},'credit',+this.value||0)">
        </td>
        <td style="padding:4px 6px">
          <button class="btn btn-sm btn-ghost" onclick="delOdLigne(${i})" style="padding:3px 8px">✕</button>
        </td>
      </tr>`;
    }).join("") +
    `<tr style="background:var(--papier)">
      <td colspan="2" style="padding:6px 6px;font-size:11px;font-weight:600">Totaux</td>
      <td style="padding:6px;text-align:right;font-family:monospace;font-weight:700;font-size:12px;color:var(--ok)" id="od-tot-deb">
        ${fcfa(window._odLignes.reduce((s,l)=>s+(+l.debit||0),0))}
      </td>
      <td style="padding:6px;text-align:right;font-family:monospace;font-weight:700;font-size:12px;color:var(--mag)" id="od-tot-cred">
        ${fcfa(window._odLignes.reduce((s,l)=>s+(+l.credit||0),0))}
      </td>
      <td></td>
    </tr>`;
  };

  modal(`<h2>✏️ Saisie d'écriture comptable</h2>
  <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;margin-bottom:12px">
    <div class="field"><label>Date *</label><input id="od-date" type="date" value="${todayISO()}"></div>
    <div class="field"><label>Journal</label>
      <select id="od-jnl">
        <option value="OD">OD — Opérations diverses</option>
        <option value="VE">VE — Ventes / Clients</option>
        <option value="AC">AC — Achats / Fournisseurs</option>
        <option value="BQ">BQ — Banque</option>
        <option value="CA">CA — Caisse</option>
        <option value="SA">SA — Salaires</option>
        <option value="AN">AN — À-Nouveau</option>
      </select>
    </div>
    <div class="field"><label>N° Pièce</label><input id="od-piece" placeholder="ex: VE-2026-001"></div>
  </div>
  <div class="field" style="margin-bottom:12px"><label>Libellé général *</label>
    <input id="od-lib" placeholder="ex: Facture FAC-2026-0047 — BANQUE AFRICAINE DE DEVELOPPEMENT">
  </div>
  <div style="overflow-x:auto;margin-bottom:8px">
    <table style="width:100%;border-collapse:collapse;font-size:12px">
      <thead><tr style="background:var(--papier)">
        <th style="padding:6px 6px;text-align:left;width:150px">Compte</th>
        <th style="padding:6px 6px;text-align:left">Libellé ligne</th>
        <th style="padding:6px 6px;text-align:right;width:110px">Débit</th>
        <th style="padding:6px 6px;text-align:right;width:110px">Crédit</th>
        <th style="width:32px"></th>
      </tr></thead>
      <tbody id="od-tbody"></tbody>
    </table>
  </div>
  <button class="btn btn-sm" onclick="addOdLigne()" style="margin-bottom:12px">+ Ajouter une ligne</button>
  <div style="font-size:10.5px;padding:7px 10px;background:rgba(0,174,239,.08);border-radius:6px;color:var(--cyan)">
    <strong>💡 Comptes tiers :</strong> Pour une facture client → Débit <strong>4111XXXX</strong> (ex: 41110047 BAD) / Crédit <strong>70110000</strong>.
    Pour un fournisseur → Débit <strong>60XXXXXX</strong> / Crédit <strong>4011XXXX</strong>.
  </div>
  <div class="modal-actions">
    <button class="btn" onclick="closeOverlays()">Annuler</button>
    <button class="btn btn-primary" onclick="saveEcritureOD()">Valider l'écriture</button>
  </div>`);
  setTimeout(renderOdLignes, 50);
}

function getTiersFromCompte(compte){
  if(!compte) return "";
  if(compte.startsWith("4111") && compte!=="41110000"){
    const c=(DB.clients||[]).find(x=>(x.compteComptable||x.compte_comptable)===compte);
    if(c) return "👤 "+esc(c.nom);
    const p=(DB.planCompta||[]).find(x=>x.compte===compte);
    if(p) return esc(p.libelle||"");
  }
  if(compte.startsWith("4011") && compte!=="40110000"){
    const f=(DB.fournisseurs||[]).find(x=>(x.compteComptable||x.compte_comptable)===compte);
    if(f) return "🏭 "+esc(f.nom);
    const p=(DB.planCompta||[]).find(x=>x.compte===compte);
    if(p) return esc(p.libelle||"");
  }
  return "";
}

function updOdLigne(i,k,v){
  if(!window._odLignes) return;
  window._odLignes[i][k]=v;
  // Mise à jour visuelle : tiers + totaux
  const tr=document.getElementById("od-tr-"+i);
  if(tr && k==="compte"){
    const tiers=getTiersFromCompte(v);
    const tiersEl=tr.querySelector(".od-tiers");
    if(tiersEl) tiersEl.textContent=tiers;
    else if(tiers){
      const inpCell=tr.querySelector("td:first-child");
      if(inpCell){
        const d=document.createElement("div");
        d.className="od-tiers";
        d.style.cssText="font-size:10px;color:var(--cyan);margin-top:2px";
        d.textContent=tiers;
        inpCell.appendChild(d);
      }
    }
  }
  // Mettre à jour les totaux
  const totD=window._odLignes.reduce((s,l)=>s+(+l.debit||0),0);
  const totC=window._odLignes.reduce((s,l)=>s+(+l.credit||0),0);
  const elD=document.getElementById("od-tot-deb");
  const elC=document.getElementById("od-tot-cred");
  if(elD) elD.textContent=fcfa(totD);
  if(elC) elC.textContent=fcfa(totC);
}

function addOdLigne(){
  if(!window._odLignes) window._odLignes=[];
  window._odLignes.push({compte:"",libelle:"",debit:0,credit:0});
  // Re-render tbody
  const tmpModal=document.querySelector(".modal-wrap") || document.querySelector("[id^='od-tbody']")?.closest(".modal-wrap");
  openSaisieCompta({lignes:window._odLignes});
}

function delOdLigne(i){
  if(!window._odLignes||window._odLignes.length<=1) return;
  window._odLignes.splice(i,1);
  openSaisieCompta({lignes:window._odLignes});
}

async function saveEcritureOD(){
  const gv=id=>document.getElementById(id)?.value?.trim()||"";
  const date=gv("od-date"); if(!date){toast("Date requise");return;}
  const libelle=gv("od-lib"); if(!libelle){toast("Libellé requis");return;}
  const piece=gv("od-piece")||"OD-"+Date.now().toString().slice(-4);
  const jnl=gv("od-jnl")||"OD";
  const lignes=window._odLignes||[];
  const findLib=c=>(DB.planCompta||[]).find(p=>p.compte===c)?.libelle||"";

  // Vérifier équilibre débit = crédit
  const totD=lignes.reduce((s,l)=>s+(+l.debit||0),0);
  const totC=lignes.reduce((s,l)=>s+(+l.credit||0),0);
  if(Math.round(totD)!==Math.round(totC)){
    toast(`⚠️ Déséquilibre : Débit ${fcfa(totD)} ≠ Crédit ${fcfa(totC)}`,"warning");
    return;
  }
  if(totD===0){toast("Montants requis");return;}

  const entries=[];
  for(const l of lignes){
    if((!l.debit&&!l.credit)||!l.compte) continue;
    entries.push({
      id:crypto.randomUUID(),date,journal_code:jnl,
      libelle:l.libelle||libelle,reference:libelle,numero_piece:piece,
      compte_num:l.compte,compte_lib:findLib(l.compte),
      debit:+l.debit||0,credit:+l.credit||0,tva:0
    });
  }
  if(!entries.length){toast("Aucune ligne valide (compte + montant requis)");return;}
  let echecs=0;
  for(const e of entries){
    const ok=await dbUpsert("journal_entries",e);
    if(ok){ (DB.journal=DB.journal||[]).push(e); } else { echecs++; }
  }
  if(echecs){
    toast(`⚠️ ${echecs} ligne(s) sur ${entries.length} n'ont PAS pu être enregistrées — voir la console pour l'erreur exacte`);
    if(echecs===entries.length) return; // rien n'a été sauvé, ne pas fermer la modale
  } else {
    toast(`✅ Écriture ${jnl} — ${entries.length} ligne(s) — Débit/Crédit : ${fcfa(totD)}`);
  }
  window._odLignes=null;
  closeOverlays();
  renderComptaTab();
}

async function saveEmploye(id){
  if(!guard("crh"))return;
  const g=i=>document.getElementById(i)?.value?.trim()||"";
  const n=i=>+document.getElementById(i)?.value||0;
  const prenom=g("emp-prenom")||g("emp-nom");
  if(!prenom){toast("Prénom obligatoire");return;}
  const data={
    prenom:prenom,
    nom:g("emp-nom"),
    tel:g("emp-tel"),email:g("emp-email"),
    cni:g("emp-cni"),
    situationMatrimoniale:g("emp-matrimonial"),
    diplome:g("emp-diplome"),
    nbEnfants:n("emp-enfants"),
    departement:g("emp-dep"),
    poste:g("emp-poste"),
    type_contrat:g("emp-ctr"),
    date_embauche:g("emp-debut"),
    salaire_brut:n("emp-salaire-brut"),
    salaire_net:n("emp-salaire-net"),
    statut:g("emp-statut"),
    cnps_number:g("emp-cnps"),
    categorie:g("emp-cat"),
    cvNotes:g("emp-cv"),
    notes:g("emp-notes")
  };
  // L'écriture est attendue : le message de succès ne doit jamais s'afficher
  // si Postgres a refusé la ligne, sinon la donnée semble enregistrée alors
  // qu'elle est perdue au prochain rechargement.
  let ok=false;
  if(id){
    const x=(DB.employes||[]).find(e=>e.id===id);
    if(x) Object.assign(x,data);
    ok=await dbUpsert("crm_employes",{id,...data}).catch(err=>{console.error(err);toast("⚠ Réseau : "+(err&&err.message||err),9000);return false;});
  } else {
    const x={id:uid(),...data,createdAt:new Date().toISOString()};
    (DB.employes=DB.employes||[]).push(x);
    ok=await dbUpsert("crm_employes",x).catch(err=>{console.error(err);toast("⚠ Réseau : "+(err&&err.message||err),9000);return false;});
  }
  if(!ok) return;              // le toast d'erreur de dbUpsert reste affiché
  closeOverlays();toast(id?"Employé mis à jour ✓":"Employé créé ✓");go(current);
}
